'use strict';
const DATA=window.CARE_DATA, FILES=window.CARE_FILES;
const NOW='2026-11-09', CLOCK='2026-11-09T08:00:00-05:00', KEY='carethread-v1';
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>Array.from(root.querySelectorAll(q));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',queue:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',task:'M9 11l3 3L22 4 M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',chart:'M3 3v18h18 M7 14l4-4 4 3 6-8',database:'M21 5c0 2-4 3-9 3S3 7 3 5s4-3 9-3 9 1 9 3z M3 5v14c0 2 4 3 9 3s9-1 9-3V5 M3 12c0 2 4 3 9 3s9-1 9-3',play:'M8 4l13 8-13 8z',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',sun:'M12 3v1 M12 20v1 M3 12h1 M20 12h1 M5.6 5.6l.7.7 M17.7 17.7l.7.7 M5.6 18.4l.7-.7 M17.7 6.3l.7-.7 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M21 13A9 9 0 1 1 11 3a7 7 0 0 0 10 10',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',close:'M6 6l12 12 M18 6L6 18',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',phone:'M22 16.9v3a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 3 5.2 2 2 0 0 1 5 3h3l2 5-3 2a16 16 0 0 0 7 7l2-3z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',split:'M3 3h18v18H3z M14 3v18',layout:'M3 3h18v18H3z M3 8h18 M8 8v13',pin:'M16 3l5 5-4 1-3 5-1 5-3-3-6 6 M8 3l13 13 M8 3l1 4-5 3',more:'M5 12h.01 M12 12h.01 M19 12h.01',alert:'M12 3l10 18H2z M12 9v4 M12 17h.01',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',refresh:'M21 2v6h-6 M3 22v-6h6 M3.5 9a9 9 0 0 1 15-4L21 8 M3 16l2.5 3a9 9 0 0 0 15-4',arrow:'M5 12h14 M13 6l6 6-6 6',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',panel:'M3 3h18v18H3z M9 3v18',home:'M3 10l9-7 9 7v11h-6v-7H9v7H3z',mail:'M3 5h18v14H3z M3 5l9 8 9-8',edit:'M16 3l5 5-12 12-6 1 1-6z M14 5l5 5',hospital:'M4 22V5h16v17 M9 2h6v6H9z M9 22v-6h6v6 M7 11h2 M15 11h2'};
const I=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const btn=(action,text,icon='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${icon?I(icon):''}${text}</button>`;
const ib=(action,label,icon,extra='')=>`<button type="button" class="iconbtn" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${extra}>${I(icon)}</button>`;
const pill=(text,color='')=>`<span class="pill ${color}">${esc(text)}</span>`;
const date=v=>v?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(v.length===10?v+'T12:00:00Z':v)):'Unknown';
const initials=p=>p.name.replace('Demo ','').split(' ').map(x=>x[0]).join('');
const pname=p=>p.name.replace('Demo ','');
const avatar=(p,big=false)=>`<span class="avatar c${DATA.patients.indexOf(p)} ${big?'big':''}" aria-hidden="true">${initials(p)}</span>`;
const recordRows=(name,id)=>{let s=DATA.sheets.find(x=>x.name===name);let col=s.headers.indexOf('Member ID');return s.rows.filter(r=>r[col]===id).map(r=>Object.fromEntries(s.headers.map((h,i)=>[h,r[i]])));};
const patient=id=>DATA.patients.find(p=>p.id===id);
let storageAvailable=true;
function initial(){return {theme:'light',role:'Case manager',view:'dashboard',active:'home',tabs:[],pinned:[],patientSection:{},filters:{search:'',tier:'all',status:'all',program:'all'},timelineFilter:'all',tasks:DATA.sheets.find(x=>x.name==='Tasks referrals').rows.map((r,i)=>({id:r[0],member:r[1],title:r[2],owner:r[3],due:r[4],status:r[5],evidence:'',type:i>2?'Referral':'Task',referral:i>2?'Accepted':'Requested',service:i===3?'Demo Housing Link':i===4?'Demo Home Support':'',priority:'P1'})),cases:Object.fromEntries(DATA.patients.map((p,i)=>[p.id,{status:i>2?'Active':'Outreach',owner:'Maria RN',goal:p.goal,barrier:p.barrier,closedReason:'',override:null}])),drafts:{},contacts:[],notes:[],assessment:{},audit:[],readNotifications:[],snoozed:[],context:true,dockOpen:false,contextWidth:300,dockHeight:250,sidebarCollapsed:false,compact:false,exportPeriod:'snapshot'};}
let S;try{S=JSON.parse(localStorage.getItem(KEY))||initial();if(!S.cases||!S.tasks)S=initial();}catch{S=initial();storageAvailable=false;}
let modal=null,drawer=null,toastTimer=null,tour=null,tourSnapshot=null,dragTab=null,previousFocus=null;
const allCases=()=>DATA.patients.map(p=>({...p,case:S.cases[p.id]}));
let effectiveTier=p=>{const o=S.cases[p.id].override;return o&&o.expiry>=NOW?o.tier:p.priority;};
const openTasks=id=>S.tasks.filter(t=>(!id||t.member===id)&&!['Completed','Cancelled'].includes(t.status));
let overdue=t=>t.due<NOW&&!['Completed','Cancelled'].includes(t.status);
const isClosed=p=>S.cases[p.id].status==='Closed';
function persist(){if(tour)return;try{localStorage.setItem(KEY,JSON.stringify(S));storageAvailable=true;}catch{storageAvailable=false;toast('Storage is unavailable. Download a backup before closing this page.');}}
function audit(action,id='',detail=''){S.audit.unshift({at:new Date().toISOString(),action,member:id,detail,actor:S.role==='Supervisor'?'Demo Sam, Supervisor':'Demo Maria RN'});persist();}
function toast(text){$('#toast')?.remove();const el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4200);}
function goto(view){S.active='home';S.view=view;S.filters.search='';persist();render();}
function openPatient(id){if(!patient(id))return;if(!S.tabs.includes(id))S.tabs.push(id);S.active=id;S.patientSection[id]??='overview';persist();render();}
function section(id,name){S.patientSection[id]=name;persist();render();}
function draftFor(id){return S.drafts[id]||{text:'',reviewed:false,saved:true};}
function notifications(){return DATA.patients.map(p=>({id:p.id,member:p.id,title:p.id==='SYN-004'?'Housing referral needs follow-through':p.id==='SYN-001'?'Medication sources disagree':p.id==='SYN-003'?'A new ED event needs review':p.id==='SYN-005'?'Home-health start is unconfirmed':'Possible medication supply gap',detail:p.reason,kind:p.id==='SYN-004'?'Overdue task':'Review',read:S.readNotifications.includes(p.id)})).filter(n=>!S.snoozed.includes(n.id));}
function appHeader(){const labels={dashboard:'Overview',queue:'Work queue',cases:'Cases',tasks:'Tasks & referrals',insights:'Insights',sources:'Data sources',journeys:'User journeys',exports:'Downloads',settings:'Preferences',audit:'Activity log'};return `<div class="app"><aside class="sidebar"><div class="brand row"><svg class="brandmark" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M24 7C12-1 0 12 9 23c5 6 16 3 16-4 0-6-9-8-13-2" stroke="currentColor" stroke-width="3.4" stroke-linecap="round"/></svg><span>CareFlow</span></div><div class="workspace-label eyebrow">Clinical workspace</div><nav class="navgroup" aria-label="Main navigation">${[['dashboard','grid','Overview'],['queue','queue','Work queue'],['cases','people','Cases'],['tasks','task','Tasks & referrals'],['insights','chart','Insights'],['sources','database','Data sources']].map(([v,i,l])=>`<button class="nav ${S.active==='home'&&S.view===v?'active':''}" data-action="nav" data-view="${v}" aria-label="${l}" title="${l}" data-tour="nav-${v}" ${S.active==='home'&&S.view===v?'aria-current="page"':''}>${I(i)}<span class="nav-label">${l}</span>${v==='queue'?`<span class="count">${DATA.patients.filter(p=>!isClosed(p)).length}</span>`:v==='tasks'?`<span class="count">${openTasks().length}</span>`:''}</button>`).join('')}</nav><div class="workspace-label eyebrow" style="padding-top:29px">Explore</div><nav class="navgroup" aria-label="Explore"><button class="nav ${S.view==='journeys'&&S.active==='home'?'active':''}" data-action="nav" data-view="journeys" aria-label="User journeys" title="User journeys" data-tour="nav-journeys">${I('play')}<span class="nav-label">User journeys</span><span class="count">5</span></button><button class="nav ${S.view==='exports'&&S.active==='home'?'active':''}" data-action="nav" data-view="exports" aria-label="Downloads" title="Downloads">${I('download')}<span class="nav-label">Downloads</span></button></nav><div class="sidebar-bottom"><button class="nav" style="width:100%" data-action="nav" data-view="settings" aria-label="Preferences" title="Preferences">${I('settings')}<span class="nav-label">Preferences</span></button><div class="demo-info"><div class="row" style="gap:6px;margin-bottom:5px"><span class="dot" style="color:var(--green)"></span> Synthetic workspace</div>5 fictional members. Changes stay in this browser.</div><button class="profile row" data-action="profile" aria-label="Demo profile and role"><span class="avatar">MR</span><span class="profile-text"><strong>Maria Rodriguez</strong><small>${esc(S.role)} · demo role</small></span></button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb row">${ib('sidebar','Toggle sidebar','panel')}<span>Care management</span><span>/</span><span style="color:var(--ink)">${S.active==='home'?labels[S.view]:esc(pname(patient(S.active)))}</span></div><div class="top-actions row"><button class="command-search" data-action="search" aria-label="Search patients and cases">${I('search')}<span>Search workspace</span><kbd class="key">⌘ K</kbd></button>${btn('journeys','Play a journey','play','quiet journey-top','data-tour="journey-launcher"')}${ib('theme',S.theme==='dark'?'Switch to light mode':'Switch to dark mode',S.theme==='dark'?'sun':'moon')}${ib('notifications','Notifications','bell',`data-tour="notifications"`)}</div></header><div class="tabbar" role="tablist" aria-label="Open workspace tabs"><button class="tab ${S.active==='home'?'active':''}" role="tab" aria-selected="${S.active==='home'}" data-action="home-tab">${I('home')} Workspace</button>${S.tabs.map(id=>{let p=patient(id);return `<div class="tab ${S.active===id?'active':''}" draggable="true" data-tab="${id}"><button role="tab" aria-selected="${S.active===id}" data-action="open" data-id="${id}">${S.pinned.includes(id)?I('pin'):''}${esc(pname(p))} ${!S.readNotifications.includes(id)?'<span class="badge-count" title="Unread update">1</span>':''} ${draftFor(id).text&&!draftFor(id).saved?'<span class="unsaved">●</span>':''}</button><button class="close" data-action="close-tab" data-id="${id}" aria-label="Close ${esc(pname(p))} tab">×</button></div>`;}).join('')}</div><div class="page" id="page">${S.active==='home'?homeView():patientView(patient(S.active))}</div><footer class="statusbar"><div class="row"><span>${I('shield')} Synthetic data only</span><span class="optional">${storageAvailable?'Saved in this browser':'Storage unavailable'}</span></div><div class="row"><span>Mon, Nov 9, 2026 · 08:00 ET</span><button data-action="shortcuts" class="optional">Keyboard shortcuts</button></div></footer></main></div>`;}
function homeView(){switch(S.view){case 'queue':return queuePage();case 'cases':return casesPage();case 'tasks':return tasksPage();case 'insights':return insightsPage();case 'sources':return sourcesPage();case 'journeys':return journeysPage();case 'exports':return exportsPage();case 'settings':return settingsPage();case 'audit':return auditPage();default:return dashboard();}}
function sortedPatients(){return DATA.patients.slice().sort((a,b)=>{const ta=effectiveTier(a),tb=effectiveTier(b);if(ta!==tb)return ta.localeCompare(tb);const oa=openTasks(a.id).filter(overdue).length,ob=openTasks(b.id).filter(overdue).length;if(oa!==ob)return ob-oa;return ['SYN-001','SYN-005','SYN-003','SYN-002'].indexOf(a.id)-['SYN-001','SYN-005','SYN-003','SYN-002'].indexOf(b.id);});}
function filteredPatients(){return sortedPatients().filter(p=>{let q=S.filters.search.toLowerCase();return (!q||`${p.name} ${p.id} CASE-${p.id} ${p.scenario}`.toLowerCase().includes(q))&&(S.filters.tier==='all'||effectiveTier(p)===S.filters.tier)&&(S.filters.status==='all'||S.cases[p.id].status===S.filters.status)&&(S.filters.program==='all'||p.plan.includes(S.filters.program));});}
const shortReasons={'SYN-001':['Medication sources disagree','Discharged Nov 6 · heart failure'],'SYN-002':['Possible refill gap','Verify actual supply and affordability'],'SYN-003':['Contact route is invalid','Nov 7 ED event · details missing'],'SYN-004':['Housing follow-up overdue','Referral sent · service not received'],'SYN-005':['Home-health start unconfirmed','Recent discharge · caregiver support']};
const bestTimes={'SYN-001':'Morning','SYN-002':'After 17:30','SYN-003':'Verify route','SYN-004':'14:00','SYN-005':'After 16:00'};
function reasonFor(p){const base=shortReasons[p.id].slice();if(p.id==='SYN-004'&&!openTasks(p.id).some(overdue))base[0]='Housing follow-up pending';if(['SYN-001','SYN-005'].includes(p.id)&&S.assessment[p.id]?.reconciliation)base[0]=p.id==='SYN-001'?'Transition follow-up':'Home-support follow-up';return base;}
function queueTable(list=filteredPatients()){return list.length?`<div class="table-wrap"><table class="queue-table"><thead><tr><th>Member</th><th>Priority</th><th>Needs attention</th><th class="when">Contact</th><th class="optional">Case state</th><th><span class="sr-only">Open case</span></th></tr></thead><tbody>${list.map(p=>`<tr><td><button class="patient-link" data-action="open" data-id="${p.id}" data-tour="open-${p.id}">${avatar(p)}<span><strong>${esc(pname(p))}</strong><small>${p.id} · ${p.age} years</small></span></button></td><td>${pill(effectiveTier(p),effectiveTier(p)==='P1'?'amber':'')}</td><td class="reason"><strong>${reasonFor(p)[0]}</strong><span>${reasonFor(p)[1]}</span></td><td class="when nowrap muted small">${bestTimes[p.id]}</td><td class="optional">${pill(S.cases[p.id].status,isClosed(p)?'green':'')}</td><td>${ib('open','Open '+pname(p),'chevron',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No cases match these filters','Try another name, priority, or case state.');}
function empty(title,desc){return `<div class="empty">${I('queue')}<h3>${title}</h3><p>${desc}</p></div>`;}
function sourceEventChart(){const rows=DATA.sheets.find(x=>x.name==='Hospital alerts').rows;const events=[...new Map(rows.filter(r=>r[4]).map(r=>[r[2]+'|'+r[3],r])).values()];let counts=Array.from({length:7},(_,i)=>{let day='2026-11-'+String(i+3).padStart(2,'0');return events.filter(r=>r[4].startsWith(day)).length;});const pts=counts.map((n,i)=>`${25+i*48},${100-n*48}`).join(' ');return `<svg class="chart" viewBox="0 0 340 130" role="img" aria-label="Hospital event dates: ${counts.join(', ')} events from November 3 to 9"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="currentColor" stop-opacity=".1"/><stop offset="100%" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><path d="M25 52H315 M25 100H315" class="chart-gridline"/><polygon points="25,100 ${pts} 313,100" fill="url(#chartfill)" style="color:var(--green)"/><polyline points="${pts}" class="chart-line"/>${counts.map((n,i)=>`<circle cx="${25+i*48}" cy="${100-n*48}" r="3" fill="var(--green)"/><text x="${25+i*48}" y="124" text-anchor="middle" class="chart-label">${i+3} Nov</text>`).join('')}</svg>`;}
function needBars(){const groups=[['Transitions',2],['Access & refills',1],['Outreach',1],['Social support',1]];return groups.map(([l,n])=>`<div class="bar-row"><span class="muted">${l}</span><span class="bar-track"><span class="bar-fill" style="display:block;width:${n/5*100}%"></span></span><strong>${n}</strong></div>`).join('');}
function dashboard(){const active=DATA.patients.filter(p=>!isClosed(p)),p1=active.filter(p=>effectiveTier(p)==='P1').length,over=openTasks().filter(overdue).length,done=S.tasks.filter(t=>t.status==='Completed').length;return `<div class="page-inner"><div class="page-head spread"><div><div class="eyebrow" style="margin-bottom:8px">Monday, November 9</div><h1>Good morning, <span class="greeting-accent">Maria.</span></h1><p>A clear view of who needs you today.</p></div><div class="row">${btn('export-menu','Export','download')}${btn('nav','Open work queue','arrow','primary','data-view="queue"')}</div></div><div class="metrics">${[[active.length,'Active cases','In this five-member demo','cases'],[p1,'Priority reviews','Clinical review, not emergencies','queue'],[openTasks().length,'Open actions',`${over} overdue · ${done} completed`,'tasks'],[new Set(S.contacts.filter(c=>c.outcome.startsWith('Reached')).map(c=>c.member)).size,'Members reached','Logged during your session','insights']].map(([n,l,c,v])=>`<button class="metric" data-action="nav" data-view="${v}"><div class="metric-label">${l}</div><div class="num">${n.toString().padStart(2,'0')}</div><div class="caption">${c}</div></button>`).join('')}</div><div class="dashboard-grid"><div><section class="section"><div class="section-title spread"><h2>Needs your attention</h2><button class="actionlink" data-action="nav" data-view="queue">View queue ${I('arrow')}</button></div>${queueTable(sortedPatients().filter(p=>!isClosed(p)))}</section><div class="chart-grid"><section><div class="section-title spread"><h3>Recent hospital events</h3><span class="tiny muted">Nov 3–9</span></div>${sourceEventChart()}<div class="tiny muted">3 unique source events · duplicate delivery removed</div></section><section><h3>Work by need</h3>${needBars()}<div class="tiny muted">Primary scenario for each of 5 members</div></section></div></div><aside class="focus-panel"><div class="spread"><h3>Today’s rhythm</h3>${I('clock')}</div><div class="focus-items">${[['SYN-004','Overdue','Housing referral status'],['SYN-001','This morning','A safe transition home'],['SYN-005','After 16:00','Support for Casey’s daughter'],['SYN-002','After 17:30','A call around Jordan’s work']].map(([id,time,title])=>`<button class="focus-item ${id==='SYN-004'?'overdue':''}" data-action="open" data-id="${id}"><span class="focus-time">${time}</span><strong>${title}</strong><span class="small">${pname(patient(id))} ${I('chevron')}</span></button>`).join('')}</div><div class="focus-footer">Prepare now. Contact at the member’s preferred time.</div><div style="margin-top:27px;padding-top:20px;border-top:1px solid var(--line)"><div class="row">${I('play')}<h3>See the workflow</h3></div><p class="small muted" style="margin:10px 0 15px">Five guided journeys, using the patients in your queue.</p>${btn('journeys','Choose a journey','arrow','small')}</div></aside></div></div>`;}
function filters(){return `<div class="filterbar"><input type="search" placeholder="Find a member or case…" aria-label="Filter cases" data-filter="search" value="${esc(S.filters.search)}"><select aria-label="Priority filter" data-filter="tier"><option value="all">All priorities</option>${['P0','P1','P2','P3'].map(x=>`<option ${S.filters.tier===x?'selected':''}>${x}</option>`).join('')}</select><select aria-label="Case state filter" data-filter="status"><option value="all">All states</option>${['New','Review','Outreach','Active','Monitoring','Closed'].map(x=>`<option ${S.filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select aria-label="Plan filter" data-filter="program"><option value="all">All plans</option>${['Medicare','Medicaid','Commercial'].map(x=>`<option ${S.filters.program===x?'selected':''}>${x}</option>`).join('')}</select>${btn('clear-filters','Clear','','quiet small')}${btn('export-queue','CSV','download','small')}</div>`;}
function queuePage(){return `<div class="page-inner"><div class="page-head spread"><div><h1>Work queue</h1><p>Priority explains why. Contact time tells you when.</p></div>${btn('queue-policy','How priorities work','shield')}</div>${filters()}<div id="queue-results">${queueTable()}</div><p class="small muted" style="margin-top:20px">Sorted by priority, overdue work, and configured follow-up dates. Unread notifications never change clinical urgency.</p></div>`;}
function casesPage(){return `<div class="page-inner"><div class="page-head spread"><div><h1>Cases</h1><p>One ongoing plan, many conversations.</p></div>${btn('create-case','New case','plus','primary')}</div>${filters()}<div class="case-grid" id="case-results">${caseCards()}</div></div>`;}
function caseCards(){let list=filteredPatients();return list.length?list.map(p=>`<article class="case-item"><div class="spread"><button class="patient-link" data-action="open" data-id="${p.id}">${avatar(p)}<span><strong>${pname(p)}</strong><small>CASE-${p.id}</small></span></button>${pill(S.cases[p.id].status,isClosed(p)?'green':'')}</div><p>${esc(S.cases[p.id].goal)}</p><div class="spread"><span class="tiny muted">${esc(S.cases[p.id].owner)} · ${openTasks(p.id).length} open actions</span><button class="actionlink" data-action="open" data-id="${p.id}">Open case ${I('arrow')}</button></div></article>`).join(''):empty('No matching cases','Adjust the filters to see your cases.');}
function taskLines(tasks,showMember=false){return tasks.length?tasks.map(t=>{let p=patient(t.member);return `<article class="task-line"><button class="taskcheck ${t.status==='Completed'?'done':''}" data-action="edit-task" data-task="${t.id}" aria-label="Review task: ${esc(t.title)}">${t.status==='Completed'?I('check'):''}</button><div class="taskbody"><button data-action="edit-task" data-task="${t.id}" style="padding:0"><h4>${esc(t.title)}</h4></button><p>${showMember?pname(p)+' · ':''}${esc(t.owner)} · ${date(t.due)}${t.referral&&t.type==='Referral'?' · '+esc(t.referral):''}</p><div class="row wrap">${pill(t.status,t.status==='Completed'?'green':overdue(t)?'amber':'')}${overdue(t)?pill('Overdue','amber'):''}${t.type==='Referral'?pill('Referral'):''}</div>${t.evidence?`<p>Evidence: ${esc(t.evidence)}</p>`:''}</div>${ib('edit-task','Edit task','edit',`data-task="${t.id}" data-tour="task-${t.member}"`)}</article>`;}).join(''):empty('No actions here','Add a task when the care plan needs a next step.');}
function tasksPage(){return `<div class="page-inner"><div class="page-head spread"><div><h1>Tasks & referrals</h1><p>A referral is complete when its outcome is verified.</p></div><div class="row">${btn('export-tasks','Export CSV','download')}${btn('new-task','Add action','plus','primary')}</div></div><div class="filterbar"><div class="segmented"><button class="${S.taskFilter!=='completed'?'active':''}" data-action="task-filter" data-filter-value="open">Open (${openTasks().length})</button><button class="${S.taskFilter==='completed'?'active':''}" data-action="task-filter" data-filter-value="completed">Completed (${S.tasks.filter(t=>t.status==='Completed').length})</button></div><span class="small muted">${openTasks().filter(overdue).length} overdue</span></div>${taskLines(S.tasks.filter(t=>S.taskFilter==='completed'?t.status==='Completed':!['Completed','Cancelled'].includes(t.status)),true)}</div>`;}
function insightsPage(){const attempts=S.contacts.length,reached=S.contacts.filter(c=>c.outcome.startsWith('Reached')).length,complete=S.tasks.filter(t=>t.status==='Completed').length,verified=S.tasks.filter(t=>t.type==='Referral'&&t.evidence).length;return `<div class="page-inner"><div class="page-head spread"><div><h1>Insights</h1><p>Actual demo activity, separate from pilot hypotheses.</p></div>${btn('export-metrics','Export metrics','download')}</div><div class="metrics">${[[attempts,'Contact attempts'],[attempts?Math.round(reached/attempts*100)+'%':'—','Connection rate'],[complete,'Completed actions'],[S.notes.length,'Signed notes']].map(([n,l])=>`<div class="metric"><div class="metric-label">${l}</div><div class="num">${n}</div><div class="caption">This browser session</div></div>`).join('')}</div><div class="insight-grid"><section><h2>Care coordination</h2><div class="insight-callout spread"><div><div class="num">${verified} / ${S.tasks.filter(t=>t.type==='Referral').length}</div><p class="small muted">Referrals with documented status evidence</p></div>${I('task')}</div><div class="tiny muted">Verified status may be unavailable or declined. It does not necessarily mean a service was delivered.</div><div class="slimline"></div><h3>Hospital event dates</h3>${sourceEventChart()}</section><section><h2>Case mix</h2>${needBars()}<div class="slimline"></div><h3>Connection by preferred language</h3>${['English','Spanish'].map(l=>{const c=S.contacts.filter(c=>patient(c.member).language===l);return `<div class="context-kv"><span>${l}</span><strong>${c.filter(x=>x.outcome.startsWith('Reached')).length} reached / ${c.length} attempts</strong></div>`;}).join('')}<p class="tiny muted" style="margin-top:14px">A five-member demonstration cannot establish clinical effectiveness or fairness.</p></section></div><section style="margin-top:35px"><div class="section-title spread"><h2>Pilot measurement plan</h2>${pill('Assumptions, not measured results','amber')}</div><table class="queue-table"><thead><tr><th>Measure</th><th>Assumed baseline</th><th>Target</th></tr></thead><tbody>${[['Preparation per case','12 minutes','7 minutes'],['Documentation per contact','10 minutes','6 minutes'],['Connection rate','25%','35%'],['On-time follow-up','65%','85%']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></section></div>`;}
function sourcesPage(){return `<div class="page-inner"><div class="page-head spread"><div><h1>Data sources</h1><p>Freshness and coverage are part of every decision.</p></div>${btn('export-data','Download dataset','download')}</div><div class="notice-line">This workspace uses the supplied synthetic annex. Feed dates are source metadata, not live connections.</div><table class="queue-table"><thead><tr><th>Source</th><th>Coverage</th><th>Quality treatment</th><th></th></tr></thead><tbody>${[['Hospital alerts','3 unique events · 4 deliveries','Duplicate event collapsed; missing detail retained'],['Clinical records','5 member records','Medication conflicts stay visible'],['Pharmacy fills','5 network dispensing records','No fill is a possible gap, not proven nonadherence'],['Claims','5 historical claims','Recent care may be absent due to reporting lag'],['Appointments','5 records / availability states','Scheduled differs from attended'],['Social assessments','5 self-reported records','Riley’s March assessment is stale'],['Contact and consent','5 permission records','Invalid numbers and scoped caregiver authority']].map(([a,b,c])=>`<tr><td><strong>${a}</strong></td><td class="muted">${b}</td><td class="reason">${c}</td><td>${ib('source-table','Inspect '+a,'chevron',`data-source="${a}"`)}</td></tr>`).join('')}</tbody></table><section style="margin-top:28px"><h2>Data strategy</h2><p class="small muted" style="margin-top:8px">The complete inventory contains 18 dataset groups, with source, freshness goals, quality handling, and MVP priority.</p><div style="margin-top:16px">${btn('strategy','View inventory','database')}${btn('nav','Activity log','clock','quiet','data-view="audit"')}</div></section></div>`;}
function auditPage(){return `<div class="page-inner"><div class="page-head spread"><div><h1>Activity log</h1><p>Changes retain their member context and reviewer.</p></div>${btn('export-audit','Export log','download')}</div>${S.audit.length?S.audit.map(a=>`<div class="audit-line"><small>${new Date(a.at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}<br>${esc(a.actor)}</small><div><strong>${esc(a.action)}</strong> ${a.member?pill(a.member):''}<p class="muted small">${esc(a.detail)}</p></div></div>`).join(''):empty('Your activity starts here','Saving a contact, changing a task, or signing a note creates an entry.')}</div>`;}
function patientView(p){const c=S.cases[p.id],sect=S.patientSection[p.id]||'overview';return `<div class="patient-page"><header class="identity"><div class="spread"><div class="row">${avatar(p,true)}<div><div class="row wrap"><h1>${esc(pname(p))}</h1>${pill(effectiveTier(p),effectiveTier(p)==='P1'?'amber':'')}${pill(c.status,isClosed(p)?'green':'')}</div><div class="identity-meta"><span>${p.id}</span><span>${p.age} years</span><span>${esc(p.language)}</span><span>${esc(p.plan)}</span></div></div></div><div class="patient-toolbar">${btn('contact','Log outreach','phone','primary',`data-id="${p.id}" data-tour="log-outreach"`)}${btn('new-task','Add action','plus','',`data-id="${p.id}" data-tour="add-action"`)}${ib('toggle-dock','Open notes dock','file',`data-id="${p.id}" data-tour="open-notes"`)}${ib('layout','Workspace layout','layout',`data-id="${p.id}"`)}${ib('case-menu','Case options','more',`data-id="${p.id}"`)}</div></div><div class="identity-meta" style="margin-top:12px"><span>CASE-${p.id}</span><span>Owner: ${esc(c.owner)}</span><span>${esc(p.scenario)}</span></div><nav class="patient-nav" aria-label="Patient record sections">${[['overview','Overview'],['timeline','Timeline'],['plan','Care plan'],['medications','Medications'],['documents','Documents']].map(([v,l])=>`<button class="${sect===v?'active':''}" data-action="section" data-id="${p.id}" data-section="${v}" data-tour="section-${v}" ${sect===v?'aria-current="page"':''}>${l}</button>`).join('')}</nav></header><div class="patient-workspace" style="grid-template-columns:${S.context?'minmax(0,1fr) 6px var(--context)':'1fr'}"><section class="patient-content" id="patient-content">${patientContent(p,sect)}</section>${S.context?`<div class="resize-v" role="separator" aria-orientation="vertical" aria-label="Resize patient context" tabindex="0" data-resize="context"></div><aside class="context">${contextPanel(p)}</aside>`:''}</div>${S.dockOpen?noteDock(p):''}</div>`;}
function patientContent(p,sect){switch(sect){case 'timeline':return `<div class="section-title spread"><h2>Patient timeline</h2><select aria-label="Timeline event type" data-field="timeline-filter"><option value="all">All events</option>${['Hospital','Clinical','Pharmacy','Appointment','Outreach','Task'].map(v=>`<option ${S.timelineFilter===v?'selected':''}>${v}</option>`).join('')}</select></div>${timeline(p)}`;case 'plan':return carePlan(p);case 'medications':return medications(p);case 'documents':return documents(p);default:return `<div class="next-action"><div class="spread"><div class="eyebrow">Next useful action</div><button class="actionlink" data-action="override" data-id="${p.id}" data-tour="priority-rationale">Why this priority?</button></div><p>${esc(p.action)}</p></div><div class="section-title spread"><h2>At a glance</h2>${btn('sources','Review source evidence','database','small',`data-id="${p.id}" data-tour="review-evidence"`)}</div><div class="summary-list"><div class="fact-block"><h3>Clinical context ${pill(p.id==='SYN-001'||p.id==='SYN-005'?'Conflicting':'Reported',p.id==='SYN-001'||p.id==='SYN-005'?'amber':'')}</h3><p>${esc(p.clinical)}</p></div><div class="fact-block"><h3>What matters to ${esc(pname(p).split(' ')[0])}</h3><p>${esc(casesGoal(p.id))}</p></div><div class="fact-block"><h3>Social & caregiver context ${pill(p.id==='SYN-003'?'Stale':'Reported',p.id==='SYN-003'?'amber':'')}</h3><p>${esc(p.social)}</p></div><div class="fact-block"><h3>Next appointment</h3><p>${date(p.appt)} · ${esc(p.apptstatus)}<br>Attendance and transport require verification.</p></div></div><div class="section-title spread"><h2>Open actions <span class="badge-count">${openTasks(p.id).length}</span></h2><button class="actionlink" data-action="section" data-id="${p.id}" data-section="plan">Care plan ${I('arrow')}</button></div>${taskLines(openTasks(p.id))}<div class="section-title spread" style="margin-top:26px"><h2>Recent events</h2><button class="actionlink" data-action="section" data-id="${p.id}" data-section="timeline">Full timeline ${I('arrow')}</button></div>${timeline(p,3)}`;}}
const casesGoal=id=>S.cases[id].goal;
function contextPanel(p){return `<section class="context-section"><div class="spread"><h3>Contact & preferences</h3>${ib('contact-settings','Edit contact preferences','edit',`data-id="${p.id}"`)}</div><p>${esc((S.assessment[p.id]||{}).contact||p.contact)}</p><div class="context-kv"><span>Language</span><strong>${esc(p.language)}</strong></div><div class="context-kv"><span>Best time</span><strong>${bestTimes[p.id]}</strong></div><div class="context-kv"><span>Phone</span><strong>${(S.assessment[p.id]?.validity||(p.id==='SYN-003'?'Disconnected':'Verified working'))==='Disconnected'?pill('Disconnected','red'):esc(S.assessment[p.id]?.phone||p.phone)}</strong></div>${p.id==='SYN-005'?pill('Daughter authorized to Dec 31','green'):p.id==='SYN-004'?pill('Neutral voicemail only','amber'):pill('Confirm participation on contact')}</section><section class="context-section"><h3>Data quality</h3><div class="notice-line" style="padding:10px;margin-bottom:12px">${esc(p.issue)}</div><button class="actionlink" data-action="sources" data-id="${p.id}">Inspect original records ${I('arrow')}</button></section><section class="context-section"><h3>Source freshness</h3><div class="mini-source"><span>Pharmacy feed</span><strong>Nov 8</strong></div><div class="mini-source"><span>Latest claim service</span><strong>${date(p.claimdate)}</strong></div><div class="mini-source"><span>Social assessment</span><strong>${p.id==='SYN-003'?'Mar 1 · stale':'Nov 4'}</strong></div><p class="tiny" style="margin-top:10px">Event time and arrival time are separate. Missing data stays unknown.</p></section><section class="context-section"><h3>Case details</h3><div class="context-kv"><span>Owner</span><strong>${esc(S.cases[p.id].owner)}</strong></div><div class="context-kv"><span>Open actions</span><strong>${openTasks(p.id).length}</strong></div><button class="actionlink" data-action="case-menu" data-id="${p.id}">Manage case ${I('chevron')}</button></section>`;}
function timelineEvents(p){let es=[];const adts=recordRows('Hospital alerts',p.id),seen=new Set();for(const r of adts){if(!r['Event time (US Eastern)'])continue;let key=r['Encounter ID']+'|'+r.Event;if(seen.has(key))continue;seen.add(key);const dup=adts.filter(x=>x['Encounter ID']===r['Encounter ID']&&x.Event===r.Event).length;es.push({at:r['Event time (US Eastern)'],type:'Hospital',title:r.Event==='Discharge'?'Hospital discharge':'Emergency department visit',desc:`Demo HIE · received ${date(r['Received time (US Eastern)'])}${dup>1?' · duplicate delivery collapsed':''}. ${p.id==='SYN-003'?'Reason and discharge details unavailable.':'Review source instructions before contact.'}`,icon:'hospital'});}
es.push({at:p.fill,type:'Pharmacy',title:p.drug+' dispensed',desc:`${p.days}-day supply recorded. Network feed as of Nov 8. Actual use and outside-network supply unknown.`,icon:'heart'});
es.push({at:p.claimdate,type:'Clinical',title:'Historical claim service',desc:p.claim+'. Received Nov 2. This is not a current clinical assessment.',icon:'file'});
es.push({at:p.appt,type:'Appointment',title:'Follow-up appointment',desc:p.apptstatus+' · attendance not established.',icon:'clock'});
if(p.id==='SYN-001')es.push({at:'2026-10-20',type:'Clinical',title:'Clinic medication list',desc:'Furosemide 20 mg daily. Nov 6 discharge list states 40 mg daily. Conflict unresolved.',icon:'alert'});
S.contacts.filter(x=>x.member===p.id).forEach(c=>es.push({at:c.date||NOW,type:'Outreach',title:c.outcome,desc:`${c.channel} · ${c.notes||'No additional clinical assessment recorded.'}`,icon:'phone'}));
S.notes.filter(x=>x.member===p.id).forEach(n=>es.push({at:NOW,type:'Clinical',title:'Note signed by '+n.author,desc:n.text,icon:'file'}));
S.tasks.filter(t=>t.member===p.id&&t.status==='Completed').forEach(t=>es.push({at:NOW,type:'Task',title:t.title+' · completed',desc:t.evidence,icon:'task'}));
return es.sort((a,b)=>b.at.localeCompare(a.at));}
function timeline(p,limit=0){let es=timelineEvents(p).filter(e=>S.timelineFilter==='all'||e.type===S.timelineFilter);if(limit)es=es.slice(0,limit);return `<div class="timeline">${es.length?es.map(e=>`<article class="timeline-item"><span class="timeline-icon">${I(e.icon)}</span><div><div class="timeline-date">${date(e.at)} ${e.at.slice(0,10)>NOW?'· Upcoming':''} · ${e.type}</div><h4>${esc(e.title)}</h4><p>${esc(e.desc)}</p>${btn('sources','Source record','link','small quiet',`data-id="${p.id}"`)}</div></article>`).join(''):empty('No events of this type','Choose All events to see the complete record.')}</div>`;}
function carePlan(p){const a=S.assessment[p.id];return `<div class="section-title spread"><h2>Patient-agreed plan</h2>${btn('edit-plan','Update plan','edit','small',`data-id="${p.id}" data-tour="edit-plan"`)}</div><div class="next-action"><div class="eyebrow">Member’s goal</div><p>${esc(casesGoal(p.id))}</p><p class="tiny muted" style="margin-top:8px">${a?.confirmed?'Confirmed in demo interaction':'Proposed or existing goal. Confirm with member before changing the plan.'}</p></div><div class="fact-block"><h3>Barriers</h3><p>${esc(S.cases[p.id].barrier)}</p></div><div class="section-title spread" style="margin-top:24px"><h2>Actions & referrals</h2>${btn('new-task','Add action','plus','small',`data-id="${p.id}"`)}</div>${taskLines(S.tasks.filter(t=>t.member===p.id))}<div class="section-title spread" style="margin-top:27px"><h2>Signed notes</h2>${btn('toggle-dock','Open documentation','file','small',`data-id="${p.id}"`)}</div>${S.notes.filter(n=>n.member===p.id).map(n=>`<article class="source-record"><div class="spread"><h3>${n.amendment?'Amendment':'Contact note'} · ${esc(n.author)}</h3>${pill('Signed','green')}</div><p class="small" style="white-space:pre-wrap">${esc(n.text)}</p>${btn('amend-note','Add amendment','edit','quiet small',`data-id="${p.id}" data-note="${n.id}"`)}</article>`).join('')||'<p class="small muted">No signed notes in this demo session.</p>'}`;}
function medications(p){return `${S.assessment[p.id]?.reconciliation?'<div class="next-action"><div class="eyebrow">Treating-team confirmation recorded</div><p>'+esc(S.assessment[p.id].reconciliation)+'</p></div>':''}<div class="section-title spread"><h2>Medication evidence</h2><div class="row">${btn('reconciliation','Record confirmation','check','small',`data-id="${p.id}"`)}${btn('new-task','Request reconciliation','plus','small',`data-id="${p.id}"`)}</div></div>${p.id==='SYN-001'?`<div class="notice-line">Two source lists disagree. The treating team must confirm the current regimen.</div><table class="queue-table"><thead><tr><th>Source</th><th>Statement</th><th>Evidence</th></tr></thead><tbody><tr><td>Nov 6 discharge</td><td>Furosemide 40 mg daily</td><td>${pill('Conflicting','amber')}</td></tr><tr><td>Oct 20 clinic</td><td>Furosemide 20 mg daily</td><td>${pill('Conflicting','amber')}</td></tr></tbody></table>`:p.id==='SYN-005'?`<div class="notice-line">Discharge and previous clinic documentation disagree on medication status. Details need confirmation with the treating team.</div>`:''}<article class="source-record"><h3>${esc(p.drug)}</h3><div class="context-kv"><span>Last observed dispense</span><strong>${date(p.fill)}</strong></div><div class="context-kv"><span>Supply recorded</span><strong>${p.days} days</strong></div><div class="context-kv"><span>Feed as of</span><strong>Nov 8, 2026</strong></div><div class="context-kv"><span>Coverage</span><strong>Plan network only</strong></div></article>${['SYN-001','SYN-002'].includes(p.id)?`<div class="next-action" style="margin-top:20px"><div class="eyebrow">Possible supply or access gap</div><p>Ask about actual supply, affordability, and outside-network fills. Dispensing records cannot prove whether medication was taken.</p></div>`:''}<button class="actionlink" data-action="sources" data-id="${p.id}" data-tour="medication-evidence">Review underlying records ${I('arrow')}</button>`;}
function documents(p){return `<div class="section-title spread"><h2>Documents & source records</h2>${btn('export-patient','Export case JSON','download','small',`data-id="${p.id}"`)}</div>${[['Clinical records','Clinical context and instructions'],['Claims','Historical utilization'],['Pharmacy fills','Network dispensing evidence'],['Assessments','Social and caregiver assessment'],['Contact permissions','Contact and disclosure permissions']].map(([name,title])=>`<article class="export-line"><div><h3>${title}</h3><p>${recordRows(name,p.id).length} synthetic record · original content preserved</p></div>${btn('source-table','Inspect','file','small',`data-source="${name}" data-id="${p.id}"`)}</article>`).join('')}`;}
function noteDock(p){const dr=draftFor(p.id);return `<div class="resize-h" role="separator" aria-orientation="horizontal" aria-label="Resize notes dock" tabindex="0" data-resize="dock"></div><section class="note-dock"><div class="dockhead"><div class="row">${I('file')}<strong>${dr.amendment?'Amendment':'Draft note'}</strong><span class="mono">${p.id}</span><span class="tiny muted" id="draft-status">${dr.saved?'Saved locally':'Unsaved changes'}</span></div><div class="row">${btn('draft-assist','Draft from evidence','edit','small quiet',`data-id="${p.id}" data-tour="draft-assist"`)}${ib('toggle-dock','Close notes dock','close',`data-id="${p.id}"`)}</div></div><div class="dock-content"><textarea aria-label="Draft note for ${pname(p)}" data-draft="${p.id}" placeholder="Capture the conversation, agreed goals, and what happens next…" data-tour="draft-text">${esc(dr.text)}</textarea><div class="dock-controls"><span class="tiny muted">Template assistance uses entered notes and source evidence. No live AI service.</span><label><input type="checkbox" data-field="review-note" data-id="${p.id}" ${dr.reviewed?'checked':''} data-tour="review-note"> I reviewed the facts and member context</label>${btn('save-draft','Save draft','','small',`data-id="${p.id}"`)}${btn('sign-note','Review & sign','check','primary small',`data-id="${p.id}" data-tour="sign-note"`)}<span class="tiny muted">Signed notes keep a version history.</span></div></div></section>`;}
const journeys=[{id:'SYN-001',title:'A safe transition home',tag:'Discharge & conflicting data',desc:'Compare medication evidence, contact Avery, create a reconciliation task, and sign a reviewed note.',result:'You preserved conflicting doses, recorded a conversation, created an owned action, and signed a source-aware note.'},{id:'SYN-002',title:'Understand the refill gap',tag:'Access & affordability',desc:'Review Jordan’s dispensing history without assuming nonadherence, then agree on a feasible next step.',result:'You treated the missing refill as a question, respected contact preferences, and documented an access follow-up.'},{id:'SYN-003',title:'Find a better way to connect',tag:'Unreachable member',desc:'Review the ED event, avoid the disconnected number, and record an alternate-route action without inventing an assessment.',result:'You kept an unknown clinical state visible and changed the outreach strategy without using an invalid number.'},{id:'SYN-004',title:'A referral needs follow-through',tag:'Housing & behavioral health',desc:'Check the overdue housing referral and document actual availability, while respecting safe contact preferences.',result:'You distinguished referral acceptance from service delivery and kept an unavailable service visible as an unmet need.'},{id:'SYN-005',title:'Support the caregiver',tag:'Caregiver & home services',desc:'Check the daughter’s authorization, verify the missing home-health start, and document a coordinated follow-up.',result:'You checked caregiver authority and left the home-health referral open until a real start could be verified.'}];
function journeysPage(){return `<div class="page-inner"><div class="page-head"><div class="eyebrow" style="margin-bottom:8px">Interactive walkthroughs</div><h1>Follow the work, <span class="greeting-accent">step by step.</span></h1><p>Click the highlighted controls. Each prompt explains the next decision.</p></div><div class="notice-line">Journeys use a temporary sandbox. Your existing workspace is restored when you finish or exit.</div><div class="journey-list">${journeys.map((j,i)=>`<article class="journey-card"><div class="spread"><span class="journey-number">0${i+1}</span>${pill(j.tag)}</div><h2>${j.title}</h2><p>${j.desc}</p><div class="row"><div class="row">${avatar(patient(j.id))}<span class="small">${pname(patient(j.id))}<br><span class="tiny muted">${j.id}</span></span></div>${btn('start-journey','Play journey','play','small',`data-id="${j.id}" data-tour="start-${j.id}"`)}</div></article>`).join('')}</div></div>`;}
function exportsPage(){return `<div class="page-inner"><div class="page-head"><h1>Downloads</h1><p>Take the workbench, the data, or a reviewable case record with you.</p></div>${[['download-html','Standalone workbench','One HTML file. Works offline, including all five guided journeys.','HTML'],['download-zip','Complete project','Workbench, editable source, synthetic data, annex, specifications and slide deck.','ZIP'],['download-annex','Synthetic patient annex','The original five-member spreadsheet, with all 13 linked datasets.','XLSX'],['export-data','Synthetic dataset','Source records and scenario metadata used by this application.','JSON'],['export-backup','Workspace backup','Tasks, contact logs, drafts, signed notes, and audit trail from this browser.','JSON'],['export-tasks','Tasks & referrals','Current task statuses, owners, due dates, and evidence.','CSV'],['download-spec','Product specification','Workflows, data strategy, boundaries, metrics, and acceptance criteria.','MD'],['download-pdf','HiLabs case presentation','The 12-slide HiLabs-branded case presentation.','PDF']].map(([a,t,desc,type])=>`<article class="export-line"><div><h3>${t}</h3><p>${desc}</p></div>${btn(a,type,'download','small')}</article>`).join('')}<div style="margin-top:25px">${btn('import-backup','Restore a workspace backup','refresh')}${btn('design-notes','Design references','link','quiet')}</div></div>`;}
function settingsPage(){return `<div class="page-inner"><div class="page-head"><h1>Make room for your work</h1><p>Comfortable defaults. A little flexibility when you need it.</p></div><div class="settings-grid"><section><h3>Appearance</h3><label>Color mode<select data-field="theme"><option value="light" ${S.theme==='light'?'selected':''}>Light</option><option value="dark" ${S.theme==='dark'?'selected':''}>Dark</option></select></label><label>Compact queue<input type="checkbox" data-field="compact" ${S.compact?'checked':''}></label><label>Collapse navigation<input type="checkbox" data-field="sidebar" ${S.sidebarCollapsed?'checked':''}></label></section><section><h3>Patient workspace</h3><label>Show patient context<input type="checkbox" data-field="context" ${S.context?'checked':''}></label><label>Open notes dock by default<input type="checkbox" data-field="dock" ${S.dockOpen?'checked':''}></label><p class="small muted">Drag the separators to resize. Drag patient tabs to reorder. Layout changes never change case data.</p><div style="margin-top:15px">${btn('reset-layout','Reset layout','layout','small')}</div></section><section><h3>Demo role</h3><p class="small muted" style="margin-bottom:15px">Role simulation, not authentication. Supervisor mode can assign cases and transfer ownership.</p>${btn('profile',S.role,'people','small')}</section><section><h3>Workspace data</h3><p class="small muted" style="margin-bottom:15px">Data stays in this browser. Download a backup before switching devices.</p>${btn('export-backup','Backup','download','small')}${btn('reset-confirm','Reset demo data','refresh','quiet small')}</section></div></div>`;}

function field(label,name,value='',type='text',hint='',extra=''){return `<div class="field ${type==='textarea'?'full':''}"><label for="f-${name}">${label}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}${hint?`<span class="hint">${hint}</span>`:''}</div>`;}
function selectField(label,name,options,value,extra=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
function showModal(title,subtitle,body,footer='',wide=false){previousFocus=document.activeElement;modal={title,subtitle,body,footer,wide};renderModal();}
function renderModal(){let host=$('#modal-root');if(!modal){host.innerHTML='';return;}host.innerHTML=`<div class="overlay" data-modal-overlay><section class="modal ${modal.wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modalhead spread"><div><h2 id="modal-title">${modal.title}</h2>${modal.subtitle?`<p class="small muted" style="margin-top:5px">${modal.subtitle}</p>`:''}</div>${ib('close-modal','Close dialog','close')}</div><div class="modalbody">${modal.body}<div id="form-error" role="alert"></div></div>${modal.footer?`<div class="modalfoot">${modal.footer}</div>`:''}</section></div>`;setTimeout(()=>{($('input:not([type=checkbox]),select,textarea,button',host))?.focus();positionTour();},20);}
function closeModal(){modal=null;$('#modal-root').innerHTML='';previousFocus?.focus?.();positionTour();}
function formError(text){$('#form-error').className='form-error';$('#form-error').textContent=text;}
function showContact(id){const p=patient(id),bad=(S.assessment[id]?.validity|| (id==='SYN-003'?'Disconnected':'Verified working'))==='Disconnected';showModal('Log outreach',`${pname(p)} · ${id} · simulated interaction`, `<div class="notice-line">${esc(S.assessment[id]?.contact||p.contact)}${bad?'<br>The listed phone is disconnected. Choose care-team coordination to seek a permitted alternate route.':''}</div><form id="contact-form" data-member="${id}"><div class="form-grid">${selectField('Channel','channel',['Phone','Care-team coordination','Secure message','Video'],bad?'Care-team coordination':'Phone')}${selectField('Outcome','outcome',['Reached patient','Reached authorized caregiver','No answer','Voicemail','Disconnected','Wrong person','Declined','Rescheduled','Alternate route requested'],bad?'Alternate route requested':id==='SYN-005'?'Reached authorized caregiver':'Reached patient')}${selectField('Person contacted','person',['Patient','Authorized daughter','Existing care team'],bad?'Existing care team':id==='SYN-005'?'Authorized daughter':'Patient')}${field('Next review date','review',NOW,'date')}${field('Conversation or attempt notes','notes','','textarea','Record only what was actually established. Failed contact does not complete an assessment.','data-tour="contact-notes"')}</div><label class="checkline"><input type="checkbox" name="permission" data-tour="contact-permission"> I checked the contact route and permission for this interaction.</label><label class="checkline"><input type="checkbox" name="participation"> Patient agreed to participate, or existing participation remains confirmed.</label><p class="tiny muted" style="margin-top:12px">Caregiver authorization: ${id==='SYN-005'?'Daughter, care coordination only, through Dec 31, 2026.':'No authorized caregiver recorded.'}</p></form><div style="margin-top:17px">${btn('sample-contact','Use scenario example','play','small quiet',`data-id="${id}" data-tour="sample-contact"`)}</div>`,`${btn('close-modal','Cancel')}${btn('save-contact','Save contact','check','primary',`data-id="${id}" data-tour="save-contact"`)}`);}
const sampleNotes={'SYN-001':'Simulated conversation: Avery confirms interest in support. Medication access and current dose need confirmation with the treating team. Follow-up is scheduled Nov 12; transport remains to be arranged.','SYN-002':'Simulated conversation after preferred work hours: Jordan reports copay difficulty. Current supply and any outside-network fills remain to be verified. Agrees to a pharmacy-access follow-up.','SYN-003':'Simulated coordination: the listed phone remains disconnected. Asked the existing care team to verify a permitted alternate contact route and Spanish-language support. Patient not reached; current clinical status and participation are unknown.','SYN-004':'Simulated call at the agreed time: Morgan requests neutral voicemail. Housing referral was sent, but no service has been received. Availability remains unknown and transport for Nov 10 needs follow-up.','SYN-005':'Simulated conversation with authorized daughter: caregiver scope confirmed. Daughter reports strain. Home-health referral was accepted but start date is not confirmed. Agrees to a callback after 16:00.'};
function saveContact(id){const f=$('#contact-form'),v=Object.fromEntries(new FormData(f)),p=patient(id);if(!f.permission.checked)return formError('Check contact permission before recording this interaction.');if(!v.notes.trim())return formError('Add a short factual note or attempt outcome.');if(!v.review||v.review<NOW)return formError('Choose a review date on or after the demonstration date, Nov 9.');if(v.person==='Authorized daughter'&&id!=='SYN-005')return formError('No caregiver authority is recorded for this member.');if(v.outcome==='Reached authorized caregiver'&&v.person!=='Authorized daughter')return formError('Choose the authorized caregiver, or change the outcome.');if(v.outcome==='Reached patient'&&v.person!=='Patient')return formError('Reached patient requires direct contact with the patient.');if((S.assessment[id]?.validity||(id==='SYN-003'?'Disconnected':'Verified working'))==='Disconnected'&&v.channel==='Phone'&&['Reached patient','Voicemail'].includes(v.outcome))return formError('This number is disconnected. Verify a new route before recording a successful phone contact.');if(id==='SYN-004'&&v.outcome==='Voicemail'&&/depression|housing|behavioral/i.test(v.notes))return formError('This member permits neutral voicemail only. Remove sensitive details from the voicemail record.');S.contacts.unshift({id:'CONTACT-'+Date.now(),member:id,case:'CASE-'+id,date:NOW,...v,participation:f.participation.checked,permission:true});if(v.outcome.startsWith('Reached')&&f.participation.checked&&!isClosed(p))S.cases[id].status='Active';audit('Contact recorded',id,v.outcome+' · '+v.channel);closeModal();render();toast('Contact recorded. Follow-up actions remain open.');return true;}
function showTask(id,taskId){const task=taskId?S.tasks.find(t=>t.id===taskId):null;id=task?.member||id||S.active!=='home'&&S.active||DATA.patients[0].id;const p=patient(id);showModal(task?'Review action':'Add action',`${pname(p)} · ${id}`,`<form id="task-form" data-member="${id}" data-task="${taskId||''}"><div class="form-grid">${selectField('Member','member',DATA.patients.map(p=>[p.id,pname(p)]),id,task?'disabled':'')}${selectField('Action type','type',['Task','Referral'],task?.type||'Task')}${field('Action','title',task?.title||(['SYN-001','SYN-005'].includes(id)?'Verify medication discrepancy with treating team':id==='SYN-003'?'Verify permitted alternate contact route':id==='SYN-002'?'Confirm medication supply and copay options':'Verify referral availability'),'text','','required')}${field('Owner','owner',task?.owner||'Maria RN')}${field('Review / due date','due',task?.due||NOW,'date')}${selectField('Status','status',['Open','In progress','Waiting external','Completed','Cancelled'],task?.status||'Open')}${field('Service / organization','service',task?.service||'')}${selectField('Referral stage','referral',['Requested','Accepted','Service received','Verified','Unavailable','Declined'],task?.referral||'Requested')}${field('Outcome evidence or cancellation reason','evidence',task?.evidence||'','textarea','Completion, service receipt, and cancellation need dated evidence or a reason.','data-tour="task-evidence"')}</div></form><div style="margin-top:16px">${btn('sample-task','Use scenario example','play','small quiet',`data-id="${id}" data-tour="sample-task"`)}</div>`,`${btn('close-modal','Cancel')}${btn('save-task','Save action','check','primary',`data-id="${id}" data-tour="save-task"`)}`);}
function saveTask(){const f=$('#task-form'),v=Object.fromEntries(new FormData(f)),old=S.tasks.find(t=>t.id===f.dataset.task);v.member=old?.member||v.member;if(!patient(v.member))return formError('Choose a member.');if(!v.title.trim()||!v.owner.trim()||!v.due)return formError('Action, owner, and review date are required.');if(['Completed','Cancelled'].includes(v.status)&&!v.evidence.trim())return formError('Add completion evidence or a cancellation reason.');if(v.type==='Referral'&&['Service received','Verified','Unavailable','Declined'].includes(v.referral)&&!v.evidence.trim())return formError('Document who confirmed this referral outcome and when.');if(v.type==='Referral'&&v.status==='Completed'&&['Requested','Accepted'].includes(v.referral))return formError('A sent or accepted referral is not complete. Verify a service outcome first.');if(v.type==='Referral'&&v.referral==='Unavailable'&&v.status==='Completed')return formError('The need remains unmet. Keep this action open or record a reasoned cancellation and alternative plan.');const task={...old,...v,id:old?.id||'TASK-'+Date.now(),priority:old?.priority||'P1'};if(old)S.tasks[S.tasks.indexOf(old)]=task;else S.tasks.push(task);audit(old?'Action updated':'Action created',task.member,task.title+' · '+task.status);closeModal();render();toast('Action saved with owner and review date.');return true;}
function showPlan(id){const c=S.cases[id];showModal('Update care plan',`${pname(patient(id))} · ${id}`,`<form id="plan-form"><div class="form-grid">${field('Member’s goal','goal',c.goal,'textarea')}${field('Barriers and support needs','barrier',c.barrier,'textarea')}</div><label class="checkline"><input type="checkbox" name="confirmed"> I confirmed these goals and changes with the patient or authorized decision-maker.</label></form>`,`${btn('close-modal','Cancel')}${btn('save-plan','Save plan','check','primary',`data-id="${id}"`)}`);}
function showSources(id,only){drawer={id,only};renderDrawer();}
function renderDrawer(){const h=$('#drawer-root');if(!drawer){h.innerHTML='';return;}const map={'Hospital alerts':'Hospital alerts','Clinical records':'Clinical records','Pharmacy fills':'Pharmacy fills','Claims':'Claims','Appointments':'Appointments','Social assessments':'Assessments','Contact and consent':'Contact permissions'};const names=drawer.only?[map[drawer.only]||drawer.only]:['Clinical records','Hospital alerts','Pharmacy fills','Claims','Appointments','Contact permissions','Assessments'];const ids=drawer.id?[drawer.id]:DATA.patients.map(p=>p.id);h.innerHTML=`<div class="drawer-overlay"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="modalhead spread"><div><h2 id="drawer-title">Original source evidence</h2><p class="small muted" style="margin-top:5px">${drawer.id?pname(patient(drawer.id))+' · '+drawer.id:'Synthetic source inventory'}</p></div>${ib('close-drawer','Close source evidence','close','data-tour="close-evidence"')}</div><div class="drawerbody"><div class="notice-line">Source statements remain intact. Conflicts require clinical confirmation.</div>${names.map(n=>ids.map(id=>recordRows(n,id).map(r=>`<article class="source-record"><h3>${esc(n)} ${!drawer.id?'· '+esc(pname(patient(id))):''}</h3>${pill(n==='Clinical records'&&['SYN-001','SYN-005'].includes(id)?'Conflicting':'Source record',n==='Clinical records'&&['SYN-001','SYN-005'].includes(id)?'amber':'')}<dl>${Object.entries(r).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${v===null||v===''?'Unknown / unavailable':esc(v)}</dd>`).join('')}</dl></article>`).join('')).join('')).join('')}</div></section></div>`;setTimeout(()=>{$('button',h)?.focus();positionTour();},20);}
function exportBlob(name,content,type='application/json'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Downloaded '+name);}
function csv(name,headers,rows){const clean=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};exportBlob(name,'\uFEFF'+[headers,...rows].map(r=>r.map(clean).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function downloadFile(key,name,type){const f=FILES[key];if(!f)return toast('That file is not included in this package.');const bytes=Uint8Array.from(atob(f),c=>c.charCodeAt(0));exportBlob(name,new Blob([bytes],{type}));}
function standaloneHTML(){const clone=document.documentElement.cloneNode(true);['app-root','modal-root','drawer-root','tour-root'].forEach(id=>{const e=clone.querySelector('#'+id);if(e)e.innerHTML='';});clone.querySelector('#toast')?.remove();clone.removeAttribute('data-theme');clone.classList.remove('sidebar-collapse','compact');return '<!DOCTYPE html>\n'+clone.outerHTML;}
function downloadHTML(){exportBlob('CareFlow_Workbench.html',standaloneHTML(),'text/html;charset=utf-8');}
function crc32(bytes){let c=0xffffffff;for(let b of bytes){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^(0xedb88320&-(c&1));}return (c^0xffffffff)>>>0;}
function zipFiles(files){const encoder=new TextEncoder(),parts=[],central=[];let off=0,clen=0;const u16=(v,o,n)=>v.setUint16(o,n,true),u32=(v,o,n)=>v.setUint32(o,n,true);for(let [name,body]of files){const nameBytes=encoder.encode(name),bytes=typeof body==='string'?encoder.encode(body):body,crc=crc32(bytes),h=new Uint8Array(30+nameBytes.length),v=new DataView(h.buffer);u32(v,0,0x04034b50);u16(v,4,20);u16(v,6,0x800);u32(v,14,crc);u32(v,18,bytes.length);u32(v,22,bytes.length);u16(v,26,nameBytes.length);h.set(nameBytes,30);parts.push(h,bytes);const ch=new Uint8Array(46+nameBytes.length),cv=new DataView(ch.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x800);u32(cv,16,crc);u32(cv,20,bytes.length);u32(cv,24,bytes.length);u16(cv,28,nameBytes.length);u32(cv,42,off);ch.set(nameBytes,46);central.push(ch);clen+=ch.length;off+=h.length+bytes.length;}const end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,8,files.length);u16(ev,10,files.length);u32(ev,12,clen);u32(ev,16,off);return new Blob([...parts,...central,end],{type:'application/zip'});}
function downloadZIP(){const files=[['index.html',standaloneHTML()],['data/synthetic-data.json',JSON.stringify(DATA,null,2)],['README.md',window.CARE_README||'Open index.html in a modern browser. All data is fictional.']];for(const [key,name]of [['annex','documents/CareFlow_Synthetic_Patients.xlsx'],['pdf','documents/CareFlow_Presentation.pdf'],['pptx','documents/CareFlow_Editable_Slides.pptx'],['spec','documents/Workbench_Specification.md'],['design','documents/Design_References.md'],['sourceJS','source/app.js'],['sourceCSS','source/style.css'],['upgradeCore','source/upgrade-core.js'],['upgradeUI','source/upgrade-ui.js'],['upgradeCSS','source/upgrade.css'],['upgradeGuide','documents/CareFlow_Upgrade_Guide.md'],['upgradeTests','tests/core.cjs'],['upgradeFixture','tests/legacy-initial.js'],['sourceBuild','rebuild.py'],['qa','QA.md'],['designNotes','DESIGN_NOTES.md']])if(FILES[key])files.push([name,Uint8Array.from(atob(FILES[key]),c=>c.charCodeAt(0))]);exportBlob('CareFlow_Complete_Project.zip',zipFiles(files));}
function showNotifications(){drawer=null;renderDrawer();const ns=notifications();showModal('Notifications','Updates need attention. Acknowledging one never completes a task.',`${btn('read-all','Mark all read','check','small quiet')}${ns.length?ns.map(n=>`<article class="notification ${n.read?'read':''}"><span class="dot" style="color:${n.read?'var(--line)':'var(--green)'};margin-top:6px"></span><div><h3>${n.title}</h3><p>${pname(patient(n.member))} · ${n.detail}</p><div class="actions">${btn('notification-open','Open case','','small',`data-id="${n.id}"`)}${btn('notification-read',n.read?'Mark unread':'Mark read','','small quiet',`data-id="${n.id}"`)}${btn('notification-snooze','Snooze for this session','','small quiet',`data-id="${n.id}"`)}</div></div></article>`).join(''):empty('No notifications','Snoozed items can be restored below.')}<div style="margin-top:16px">${btn('restore-notifications','Restore snoozed notifications','refresh','small quiet')}</div>`,btn('close-modal','Done'));}
function showCaseMenu(id){const p=patient(id),c=S.cases[id];showModal('Case options',`${pname(p)} · CASE-${id}`,`<div class="stack">${btn('lifecycle','Update status or close case','task','',`data-id="${id}"`)}${btn('transfer','Transfer ownership','people','',`data-id="${id}"`)}${btn('override','Review or override priority','shield','',`data-id="${id}"`)}${btn('pin-tab',S.pinned.includes(id)?'Unpin patient tab':'Pin patient tab','pin','',`data-id="${id}"`)}${btn('export-patient','Download case record','download','',`data-id="${id}"`)}${btn('print-patient','Print care plan / save PDF','file','',`data-id="${id}"`)}</div>`,btn('close-modal','Done'));}
function showLifecycle(id){const c=S.cases[id],open=openTasks(id);showModal('Update case state',`${pname(patient(id))} · ${id}`,`<div class="notice-line">${open.length} actions remain open. Closing requires resolution or documented handoff. Failed outreach alone is not a successful outcome.</div><form id="life-form"><div class="form-grid">${selectField('Case state','status',['New','Review','Outreach','Active','Monitoring','Closed'],c.status)}${selectField('Closure / transition reason','reason',['','Goals met','Patient declined','Screened out','Transferred','Unable to reach under approved policy'],c.closedReason||'')}${field('Outcome, policy reference, or handoff details','detail','','textarea')}${field('Receiving owner, if transferred','receiver','')}</div><label class="checkline"><input type="checkbox" name="reviewed"> I reviewed unresolved work and confirmed resolution or an accepted handoff.</label></form>`,`${btn('close-modal','Cancel')}${btn('save-lifecycle','Save state','check','primary',`data-id="${id}"`)}`);}
function showTransfer(id){showModal('Transfer case ownership','Supervisor demo role required for reassignment.',`<form id="transfer-form"><div class="form-grid">${field('Receiving owner','owner','','text','A named receiving case manager.')}${field('Handoff reason and outstanding work','reason','','textarea')}</div><label class="checkline"><input type="checkbox" name="accepted"> The receiving owner accepted the handoff.</label><label class="checkline"><input type="checkbox" name="tasks" checked> Transfer open actions with this case.</label></form>`,`${btn('close-modal','Cancel')}${btn('save-transfer','Transfer case','check','primary',`data-id="${id}"`)}`);}
function showOverride(id){const p=patient(id),o=S.cases[id].override;showModal('Why this priority?',`${pname(p)} · ${effectiveTier(p)} operational review`, `<p class="small" style="margin-bottom:14px">${esc(p.reason)}. Priority is separate from the preferred contact time: ${bestTimes[id]}.</p><div class="notice-line">No patient in this dataset has a confirmed current emergency. P0 requires clinician confirmation and the plan’s escalation protocol.</div><form id="override-form"><div class="form-grid">${selectField('Priority tier','tier',['P0','P1','P2','P3'],o?.tier||p.priority)}${field('Override expiry','expiry',o?.expiry||NOW,'date')}${field('Clinician rationale / escalation reference','reason',o?.reason||'','textarea')}</div></form>`,`${btn('remove-override','Use rule-based priority','','quiet',`data-id="${id}"`)}${btn('save-override','Save override','check','primary',`data-id="${id}"`)}`);}
function showLayout(id){showModal('Workspace layout','Identity stays visible. Notes always stay with the same member.',`<div class="stack">${btn('layout-focus','Focus · patient record only','layout','',`data-id="${id}"`)}${btn('layout-split','Split note · record and documentation','split','',`data-id="${id}"`)}${btn('layout-context','Context · patient record and side panel','panel','',`data-id="${id}"`)}${btn('reset-layout','Reset layout','refresh')}</div><p class="small muted" style="margin-top:20px">Drag panel separators to resize, or use arrow keys while the separator is focused. Patient tabs can be dragged or moved with the buttons below.</p><div class="row" style="margin-top:15px">${btn('tab-left','Move tab left','','small',`data-id="${id}"`)}${btn('tab-right','Move tab right','','small',`data-id="${id}"`)}</div>`,btn('close-modal','Done'));}
function showSearch(){showModal('Find a member or case','Search names, member IDs, case IDs, or scenarios.',`<input type="search" id="global-search" aria-label="Search workspace" placeholder="Try Avery, SYN-003, or housing…" style="width:100%"><div id="search-results">${searchResults('')}</div>`);}
function searchResults(q){const ps=DATA.patients.filter(p=>(p.name+' '+p.id+' CASE-'+p.id+' '+p.scenario).toLowerCase().includes(q.toLowerCase()));return ps.length?ps.map(p=>`<button class="search-result" data-action="search-open" data-id="${p.id}">${avatar(p)}<span><strong>${pname(p)}</strong><small>${p.id} · ${p.scenario}</small></span>${I('arrow')}</button>`).join(''):empty('No matching member','Try a name or member ID.');}
function contactSettings(id){const p=patient(id);showModal('Contact preferences',`${pname(p)} · history remains intact`, `<form id="preferences-form"><div class="form-grid">${field('Verified phone number','phone',S.assessment[id]?.phone||p.phone,'tel','Use fictional numbers only.')}${selectField('Route validity','validity',['Unknown','Verified working','Disconnected'],S.assessment[id]?.validity||(id==='SYN-003'?'Disconnected':'Verified working'))}${field('Current route and preferences','contact',S.assessment[id]?.contact||p.contact,'textarea','Document a verified change; original source data stays accessible.')}</div><label class="checkline"><input type="checkbox" name="verified"> I verified this update with the patient or an authorized source.</label></form>`,`${btn('close-modal','Cancel')}${btn('save-preferences','Save preferences','check','primary',`data-id="${id}"`)}`);}
function showStrategy(){showModal('Data strategy','18 dataset groups. Freshness targets are proposed requirements.',`<div class="table-wrap"><table class="queue-table"><thead><tr><th>Dataset</th><th>Source / freshness</th><th>Decision / quality handling</th></tr></thead><tbody>${DATA.datasets.map(r=>`<tr><td>${esc(r[0])}<br>${pill(r[6])}</td><td>${esc(r[1])}<br><span class="muted">${esc(r[3])}</span></td><td>${esc(r[7])}<br><span class="muted">${esc(r[5])}</span></td></tr>`).join('')}</tbody></table></div>`,btn('close-modal','Done'),true);}
function draftAssist(id){const p=patient(id),c=S.contacts.find(x=>x.member===id),old=draftFor(id);S.drafts[id]={...old,text:`MEMBER: ${pname(p)} (${id}) / CASE-${id}\n\nCONTACT\n${c?c.outcome+' · '+c.channel+'\n'+c.notes:'No successful contact recorded. Clinical status and current needs require verification.'}\n\nSOURCE CONTEXT\n${p.clinical}\nSource limitations: ${p.issue}.\n\nPLAN\n${casesGoal(id)}\n${openTasks(id).map(t=>'- '+t.title+' · '+t.owner+' · review '+t.due).join('\n')}\n\nThis is a template draft from synthetic source evidence and entered notes. Reviewer must confirm accuracy.`,reviewed:false,saved:true};audit('Note draft generated',id,'Deterministic template; source evidence and latest contact');render();toast('Draft prepared from source evidence. Review before signing.');}
function signReview(id){const dr=draftFor(id);if(!dr.text.trim())return toast('Add or draft a note first.');if(!dr.reviewed)return toast('Review the facts and check the confirmation before signing.');showModal('Review & sign note',`${pname(patient(id))} · ${id}`,`<div class="notice-line">This saves an immutable signed version in this browser. Later corrections use an amendment.</div><pre style="white-space:pre-wrap;font:12px/1.7 inherit;max-height:340px;overflow:auto">${esc(dr.text)}</pre>`,`${btn('close-modal','Keep editing')}${btn('confirm-sign','Sign this version','check','primary',`data-id="${id}" data-tour="confirm-sign"`)}`);return true;}

function buildSteps(id){const j=journeys.find(j=>j.id===id),p=patient(id),base=[
 ['nav-queue','queue','Start with the work queue','Review priority and the reason for attention. The queue puts overdue actions first.'],
 ['open-'+id,'open-'+id,'Open '+pname(p),'The patient tab keeps this case available while you move around the workspace.'],
 ...(id==='SYN-002'?[['section-medications','section-medications','Check the dispensing evidence','An observed refill gap is a reason to ask about access, not proof of nonadherence.'],['medication-evidence','sources','Inspect the original records','The pharmacy feed only covers the plan network. Current supply and outside-network fills are unknown.']]:[['review-evidence','sources','Review evidence before acting',id==='SYN-001'?'The 20 mg clinic list and 40 mg discharge list disagree. Preserve both and ask the treating team to reconcile.':id==='SYN-003'?'The ED alert lacks details, and the recorded phone is disconnected. Unknown is different from no problem.':id==='SYN-004'?'The housing referral was sent, but service receipt is not established. Note the neutral-voicemail preference.':'Review the daughter’s authority, through Dec 31, and the unconfirmed home-health start.']]),
 ['close-evidence','close-drawer','Return to the case','The original sources stay accessible. Now decide how to contact the member or care team.'],
 ['log-outreach','contact','Choose the outreach route',id==='SYN-003'?'Use care-team coordination to find a permitted alternate route. Do not call the known invalid number again.':id==='SYN-005'?'The authorized daughter can discuss care coordination. Respect the callback after 16:00.':'Check the member’s preferred time, language, and contact permissions.'],
 ['sample-contact','sample-contact','Load the fictional conversation','This inserts the scenario example for the walkthrough. It is clearly marked simulated and makes no real call.'],
 ['contact-permission','permission','Confirm the contact permission','Permission is specific to the person, channel, and purpose. Check the box after reviewing the source record.'],
 ['save-contact','save-contact','Record the contact outcome',id==='SYN-003'?'The patient was not reached. The system records coordination without pretending an assessment happened.':'Save what was established and what remains unknown. Open actions do not automatically complete.'],
 [(id==='SYN-004'||id==='SYN-005')?'task-'+id:'add-action',(id==='SYN-004'||id==='SYN-005')?'edit-task':'new-task',id==='SYN-004'?'Follow the housing referral':id==='SYN-005'?'Verify the home-health start':'Give the next action an owner',id==='SYN-001'?'Create a treating-team reconciliation action. The app does not change a prescription.':id==='SYN-004'?'A referral marked accepted still needs follow-through. Confirm the actual outcome.':id==='SYN-005'?'Acceptance is not proof that home services started. Keep a review date while waiting.':'Make the follow-up explicit with an owner and review date.'],
 ['sample-task','sample-task','Use the scenario follow-up',id==='SYN-004'?'The fictional service confirms a waitlist. The action stays Waiting external and the need remains unmet.':'The example preserves uncertainty and assigns a next review. No external service is booked.'],
 ['save-task','save-task','Save the action','The action becomes part of the care plan and the audit trail. Completion requires outcome evidence.'],
 ['open-notes','toggle-dock','Open the notes dock','The dock remains bound to this member and case, even if you switch patient tabs.'],
 ['draft-assist','draft-assist','Prepare a reviewable note','Template assistance combines source context, the logged interaction, and current actions. It does not invent a clinical assessment.'],
 ['review-note','review-note','Review the facts','Read the draft. Check that uncertainty, patient identity, and the agreed next action are accurate.'],
 ['sign-note','sign-note','Review before signing','A draft is editable. Signing creates a version that later changes can amend.'],
 ['confirm-sign','confirm-sign','Sign the reviewed version','This completes the journey. Your original workspace will be restored, so the walkthrough does not overwrite your work.']
 ];return base.map(([target,event,title,text])=>({target,event,title,text}));}
function startJourney(id){if(tour)endJourney(false);closeModal();drawer=null;tourSnapshot=structuredClone(S);const theme=S.theme;S=initial();S.theme=theme;S.active='home';S.view='dashboard';tour={id,index:0,steps:buildSteps(id)};render();positionTour();}
function endJourney(completed){if(!tour)return;const j=journeys.find(j=>j.id===tour.id);tour=null;S=tourSnapshot;tourSnapshot=null;modal=null;drawer=null;$('#tour-root').innerHTML='';render();if(completed)showModal('Journey complete','Your original workspace has been restored.',`<div class="journey-complete"><div style="color:var(--green);margin-bottom:12px">${I('check')}</div><h2>${j.title}</h2><p>${j.result}</p></div>`,`${btn('journeys','Choose another journey','play','primary')}${btn('close-modal','Return to workspace')}`);else toast('Journey ended. Your original workspace is restored.');}
function advanceTour(event){if(!tour)return;if(tour.steps[tour.index].event!==event)return;tour.index++;if(tour.index>=tour.steps.length)return endJourney(true);requestAnimationFrame(()=>positionTour(true));}
function positionTour(scroll=false){const host=$('#tour-root');if(!tour){host.innerHTML='';return;}const st=tour.steps[tour.index],target=$(`[data-tour="${st.target}"]`);if(target&&scroll)target.scrollIntoView({behavior:'instant',block:'nearest',inline:'nearest'});const r=target?.getBoundingClientRect(),vw=innerWidth,vh=innerHeight;const visible=r&&r.width&&r.height&&r.top<vh&&r.bottom>0;let width=Math.min(330,vw-28),left=visible?(r.left+width<vw-20?r.left:vw-width-20):vw-width-25,top=visible?(r.bottom+270<vh?r.bottom+14:Math.max(16,r.top-270)):120;left=Math.max(14,left);top=Math.min(top,vh-290);host.innerHTML=`${visible?`<div class="tour-ring" style="left:${r.left-4}px;top:${r.top-4}px;width:${r.width+8}px;height:${r.height+8}px"></div>`:''}<aside class="tour-pop" style="left:${left}px;top:${Math.max(12,top)}px" role="region" aria-label="Guided journey prompt"><div class="spread"><span class="eyebrow" style="color:var(--green)">Journey ${journeys.findIndex(j=>j.id===tour.id)+1} · ${tour.index+1} / ${tour.steps.length}</span><button class="iconbtn" data-action="exit-journey" aria-label="Exit journey">${I('close')}</button></div><h3>${st.title}</h3><p>${st.text}</p><div class="tour-progress">${tour.steps.map((_,i)=>`<span class="${i<=tour.index?'done':''}"></span>`).join('')}</div><div class="tour-actions"><span class="tiny muted">${visible?'Click the highlighted control':'Return to the current step'}</span>${btn(visible?'tour-do':'tour-return',visible?'Do this step':'Return','arrow','primary small')}</div></aside><div class="tour-banner">Journey sandbox · no real calls, messages or bookings · existing workspace restores on exit</div>`;}
function returnToStep(){if(!tour)return;const st=tour.steps[tour.index];modal=null;drawer=null;S.active=tour.index<2?'home':tour.id;S.view='queue';if(!S.tabs.includes(tour.id)&&tour.index>=2)S.tabs.push(tour.id);S.patientSection[tour.id]=st.target==='medication-evidence'?'medications':'overview';S.dockOpen=['draft-assist','review-note','sign-note','confirm-sign'].includes(st.target);render();if(['sample-contact','contact-permission','save-contact'].includes(st.target))showContact(tour.id);if(['sample-task','save-task'].includes(st.target))showTask(tour.id,['SYN-004','SYN-005'].includes(tour.id)?S.tasks.find(t=>t.member===tour.id).id:undefined);if(st.target==='close-evidence')showSources(tour.id);if(st.target==='confirm-sign')signReview(tour.id);positionTour(true);}
function render(){document.documentElement.dataset.theme=S.theme;document.documentElement.classList.toggle('sidebar-collapse',S.sidebarCollapsed);document.documentElement.classList.toggle('compact',S.compact);document.documentElement.style.setProperty('--context',S.contextWidth+'px');document.documentElement.style.setProperty('--dock',S.dockHeight+'px');$('#app-root').innerHTML=appHeader();renderModal();renderDrawer();positionTour();}
function exportTasks(){csv('CareFlow_Tasks.csv',['Task ID','Member ID','Action','Owner','Due','Status','Type','Referral stage','Evidence'],S.tasks.map(t=>[t.id,t.member,t.title,t.owner,t.due,t.status,t.type,t.referral,t.evidence]));}
function exportPatient(id){const p=patient(id);exportBlob('CareFlow_'+id+'.json',JSON.stringify({synthetic:true,asOf:CLOCK,member:p,case:S.cases[id],tasks:S.tasks.filter(t=>t.member===id),contacts:S.contacts.filter(t=>t.member===id),notes:S.notes.filter(t=>t.member===id),draft:draftFor(id),sources:DATA.sheets.filter(s=>s.headers.includes('Member ID')).map(s=>({dataset:s.name,records:recordRows(s.name,id)}))},null,2));}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;let event=a,ok=true;
switch(a){
 case 'nav':if(modal)closeModal();drawer=null;goto(el.dataset.view);event=el.dataset.view==='queue'?'queue':'nav';break;
 case 'home-tab':S.active='home';persist();render();break;
 case 'open':openPatient(id);event='open-'+id;break;
 case 'section':section(id,el.dataset.section);event='section-'+el.dataset.section;break;
 case 'clear-filters':S.filters={search:'',tier:'all',status:'all',program:'all'};persist();render();break;
 case 'close-tab':if(draftFor(id).text&&!draftFor(id).saved){toast('Save this draft before closing the tab.');break;}S.tabs=S.tabs.filter(x=>x!==id);if(S.active===id)S.active=S.tabs.at(-1)||'home';persist();render();break;
 case 'pin-tab':S.pinned=S.pinned.includes(id)?S.pinned.filter(x=>x!==id):[...S.pinned,id];persist();closeModal();render();toast(S.pinned.includes(id)?'Patient tab pinned.':'Patient tab unpinned.');break;
 case 'tab-left':case 'tab-right':{let i=S.tabs.indexOf(id),j=i+(a==='tab-left'?-1:1);if(j>=0&&j<S.tabs.length)[S.tabs[i],S.tabs[j]]=[S.tabs[j],S.tabs[i]];persist();closeModal();render();break;}
 case 'sidebar':S.sidebarCollapsed=!S.sidebarCollapsed;persist();render();break;
 case 'theme':S.theme=S.theme==='dark'?'light':'dark';persist();render();break;
 case 'search':showSearch();break;
 case 'search-open':closeModal();openPatient(id);break;
 case 'notifications':showNotifications();break;
 case 'notification-open':S.readNotifications=[...new Set([...S.readNotifications,id])];closeModal();openPatient(id);break;
 case 'notification-read':S.readNotifications=S.readNotifications.includes(id)?S.readNotifications.filter(x=>x!==id):[...S.readNotifications,id];persist();showNotifications();break;
 case 'notification-snooze':S.snoozed.push(id);persist();showNotifications();break;
 case 'read-all':S.readNotifications=DATA.patients.map(p=>p.id);persist();showNotifications();break;
 case 'restore-notifications':S.snoozed=[];persist();showNotifications();break;
 case 'contact':showContact(id);break;
 case 'sample-contact':{const f=$('#contact-form');f.notes.value=sampleNotes[id];f.participation.checked=id!=='SYN-003';if(id==='SYN-003'){f.channel.value='Care-team coordination';f.outcome.value='Alternate route requested';f.person.value='Existing care team';}else if(id==='SYN-005'){f.outcome.value='Reached authorized caregiver';f.person.value='Authorized daughter';}else{f.outcome.value='Reached patient';f.person.value='Patient';}toast('Fictional scenario example inserted. Review the permission before saving.');break;}
 case 'save-contact':ok=saveContact(id);break;
 case 'new-task':showTask(id);break;
 case 'edit-task':showTask(id,el.dataset.task);break;
 case 'sample-task':{let f=$('#task-form');if(id==='SYN-004'){f.type.value='Referral';f.service.value='Demo Housing Link';f.status.value='Waiting external';f.referral.value='Unavailable';f.evidence.value='Nov 9, simulated service confirmation: waitlist only; no housing received. Continue follow-up and explore alternatives.';}else if(id==='SYN-005'){f.type.value='Referral';f.service.value='Demo Home Support';f.status.value='Waiting external';f.referral.value='Accepted';f.evidence.value='Nov 9, simulated agency check: referral accepted; start-of-care date still pending. Maria to verify with agency and daughter.';}else{f.status.value='In progress';f.evidence.value='Nov 9, simulated follow-up plan: Maria will coordinate verification with the existing treating team. Outcome pending.';}f.due.value='2026-11-10';break;}
 case 'save-task':ok=saveTask();break;
 case 'task-filter':S.taskFilter=el.dataset.filterValue;persist();render();break;
 case 'edit-plan':showPlan(id);break;
 case 'save-plan':{const f=$('#plan-form'),v=Object.fromEntries(new FormData(f));if(!v.goal.trim()||!v.barrier.trim()){formError('Record a goal and the relevant barriers.');ok=false;break;}if(!f.confirmed.checked){formError('Confirm that the member agreed to these changes.');ok=false;break;}S.cases[id].goal=v.goal;S.cases[id].barrier=v.barrier;S.assessment[id]={...S.assessment[id],confirmed:true};audit('Care plan updated',id,'Member agreement confirmed');closeModal();render();toast('Care plan updated.');break;}
 case 'reconciliation':showModal('Record treating-team confirmation',`${pname(patient(id))} · original source lists stay unchanged.`,`<form id="reconciliation-form"><div class="form-grid">${field('Confirmed statement, source, and date','evidence','','textarea','Record the treating clinician/pharmacist confirmation. This app does not prescribe or issue medication orders.')}</div><label class="checkline"><input type="checkbox" name="confirmed"> I verified the statement with an authorized treating clinician or pharmacist.</label></form>`,`${btn('close-modal','Cancel')}${btn('save-reconciliation','Save confirmation','check','primary',`data-id="${id}"`)}`);break;
 case 'save-reconciliation':{const f=$('#reconciliation-form');if(!f.evidence.value.trim()||!f.confirmed.checked){formError('Record the dated source confirmation and check that it was verified.');ok=false;break;}S.assessment[id]={...S.assessment[id],reconciliation:f.evidence.value};audit('Treating-team confirmation recorded',id,f.evidence.value);closeModal();render();toast('Confirmation recorded. Original source statements remain available.');break;}
 case 'sources':showSources(id);break;
 case 'source-table':showSources(id,el.dataset.source);break;
 case 'close-drawer':drawer=null;renderDrawer();break;
 case 'close-modal':closeModal();break;
 case 'toggle-dock':S.dockOpen=!S.dockOpen;persist();render();break;
 case 'draft-assist':draftAssist(id);break;
 case 'save-draft':{let dr=draftFor(id);S.drafts[id]={...dr,saved:true};persist();render();toast('Draft saved to this member’s case.');break;}
 case 'sign-note':ok=signReview(id);break;
 case 'confirm-sign':{const dr=draftFor(id);if(!dr.text.trim()||!dr.reviewed){formError('Return to the draft and complete the review first.');ok=false;break;}S.notes.unshift({id:'NOTE-'+Date.now(),member:id,case:'CASE-'+id,text:dr.text,author:'Demo Maria RN',signedAt:new Date().toISOString(),amendment:dr.amendment||null});S.drafts[id]={text:'',reviewed:false,saved:true};audit('Note signed',id,dr.amendment?'Amendment to '+dr.amendment:'Reviewed clinical coordination note');closeModal();render();toast('Signed version saved.');break;}
 case 'amend-note':S.drafts[id]={text:'Amendment to '+el.dataset.note+'\n\nCorrection and reason:\n',reviewed:false,saved:true,amendment:el.dataset.note};S.dockOpen=true;persist();render();break;
 case 'case-menu':showCaseMenu(id);break;
 case 'lifecycle':showLifecycle(id);break;
 case 'save-lifecycle':{const f=$('#life-form'),v=Object.fromEntries(new FormData(f));if(v.status==='Closed'&&(!v.reason||!v.detail.trim()||!f.reviewed.checked)){formError('Closure requires a reason, outcome detail, and review of outstanding work.');ok=false;break;}if(v.status==='Closed'&&openTasks(id).length&&v.reason!=='Transferred'){formError('Resolve or cancel open actions with evidence, or document an accepted transfer.');ok=false;break;}if(v.status==='Closed'&&v.reason==='Transferred'&&!v.receiver.trim()){formError('Name the receiving owner for the accepted handoff.');ok=false;break;}if(v.reason==='Transferred'&&v.receiver.trim()){S.cases[id].owner=v.receiver;S.tasks.filter(t=>t.member===id&&!['Completed','Cancelled'].includes(t.status)).forEach(t=>t.owner=v.receiver);}S.cases[id].status=v.status;S.cases[id].closedReason=v.status==='Closed'?v.reason:'';audit('Case state updated',id,v.status+' · '+v.reason+' · '+v.detail);closeModal();render();toast('Case state saved.');break;}
 case 'transfer':showTransfer(id);break;
 case 'save-transfer':{let f=$('#transfer-form'),v=Object.fromEntries(new FormData(f));if(S.role!=='Supervisor'){formError('Switch to the Supervisor demo role to transfer ownership.');ok=false;break;}if(!v.owner.trim()||!v.reason.trim()||!f.accepted.checked){formError('Name the receiving owner, record the reason, and confirm acceptance.');ok=false;break;}S.cases[id].owner=v.owner;if(f.tasks.checked)S.tasks.filter(t=>t.member===id&&!['Completed','Cancelled'].includes(t.status)).forEach(t=>t.owner=v.owner);audit('Case transferred',id,v.owner+' · '+v.reason);closeModal();render();toast('Owner and handoff saved.');break;}
 case 'override':showOverride(id);break;
 case 'save-override':{let v=Object.fromEntries(new FormData($('#override-form')));if(!v.reason.trim()||!v.expiry||v.expiry<NOW){formError('Add the clinician rationale and a current expiry date.');ok=false;break;}S.cases[id].override=v;audit('Priority override',id,v.tier+' · '+v.reason+' · expires '+v.expiry);closeModal();render();toast('Priority override recorded.');break;}
 case 'remove-override':S.cases[id].override=null;audit('Priority override removed',id);closeModal();render();break;
 case 'queue-policy':showModal('How priorities work','Operational review rules, not an automated diagnosis.',`<div class="stack"><p class="small"><strong>P0:</strong> clinician-confirmed urgent review under a plan-approved escalation protocol.</p><p class="small"><strong>P1:</strong> recent uncontacted discharge, unresolved medication discrepancy, failed service start, overdue high-priority action, or ED event with unresolved outreach.</p><p class="small"><strong>P2:</strong> possible supply/access gap or routine follow-up due.</p><p class="small"><strong>P3:</strong> monitoring without a due action.</p><div class="notice-line">Tie-break: overdue work, due date, then event recency. Contact time stays separate. Missing data never means low risk.</div><p class="small muted">The seven-day discharge lookback is a pilot worklist assumption. Clinical teams must approve rules before real use.</p></div>`,btn('close-modal','Understood'));break;
 case 'layout':showLayout(id);break;
 case 'layout-focus':S.context=false;S.dockOpen=false;closeModal();persist();render();break;
 case 'layout-split':S.context=false;S.dockOpen=true;closeModal();persist();render();break;
 case 'layout-context':S.context=true;S.dockOpen=false;closeModal();persist();render();break;
 case 'reset-layout':S.context=true;S.dockOpen=false;S.contextWidth=300;S.dockHeight=250;S.sidebarCollapsed=false;closeModal();persist();render();toast('Default layout restored.');break;
 case 'profile':showModal('Demo profile','Role simulation only. The hosted Site remains owner-private.',`<div class="row" style="margin-bottom:22px"><span class="avatar big">MR</span><div><h3>Maria Rodriguez</h3><p class="small muted">Clinical case management · synthetic workspace</p></div></div><div class="field"><label for="role-select">Demo role</label><select id="role-select"><option ${S.role==='Case manager'?'selected':''}>Case manager</option><option ${S.role==='Supervisor'?'selected':''}>Supervisor</option></select></div>`,`${btn('close-modal','Cancel')}${btn('save-role','Apply role','check','primary')}`);break;
 case 'save-role':S.role=$('#role-select').value;audit('Demo role changed','',S.role);closeModal();render();break;
 case 'contact-settings':contactSettings(id);break;
 case 'save-preferences':{let f=$('#preferences-form');if(!f.contact.value.trim()||!f.verified.checked){formError('Record the verified preference and confirm its source.');ok=false;break;}if(f.validity.value==='Verified working'&&!/^\+?[0-9 ()-]{7,25}$/.test(f.phone.value)){formError('Enter a valid fictional phone number before verifying the route.');ok=false;break;}S.assessment[id]={...S.assessment[id],contact:f.contact.value,phone:f.phone.value,validity:f.validity.value};audit('Contact preferences updated',id,'Original source retained');closeModal();render();break;}
 case 'create-case':showModal('Create a case','This demo supports the five supplied fictional members.',`<form id="create-case-form"><div class="form-grid">${selectField('Member','member',DATA.patients.map(p=>[p.id,pname(p)]),DATA.patients[0].id)}${field('Owner','owner','Maria RN')}${field('Care goal','goal','','textarea')}</div></form><p class="small muted" style="margin-top:15px">Each supplied member already has a case. We prevent duplicate active enrollment for the same need. A closed case can reopen with a documented reason.</p>`,`${btn('close-modal','Cancel')}${btn('save-case','Create or reopen','plus','primary')}`);break;
 case 'save-case':{let v=Object.fromEntries(new FormData($('#create-case-form')));if(S.cases[v.member].status!=='Closed'){formError('An active case already exists for this member and care program. Open that case to continue.');ok=false;break;}if(!v.owner.trim()||!v.goal.trim()){formError('Provide an owner and goal/reopening reason.');ok=false;break;}S.cases[v.member]={...S.cases[v.member],status:'Review',owner:v.owner,goal:v.goal,closedReason:''};audit('Case reopened',v.member,v.goal);closeModal();openPatient(v.member);break;}
 case 'strategy':showStrategy();break;
 case 'export-menu':showModal('Export workspace','Choose a useful, reviewable format.',`<div class="stack">${btn('export-queue','Current queue · CSV','download')}${btn('export-tasks','Tasks and referrals · CSV','download')}${btn('export-backup','Workspace backup · JSON','download')}${btn('nav','All downloads','arrow','','data-view="exports"')}</div>`,btn('close-modal','Done'));break;
 case 'export-queue':{const ps=filteredPatients();csv('CareFlow_Queue.csv',['Member ID','Name','Priority','Reason','Preferred contact','State','Owner'],ps.map(p=>[p.id,pname(p),effectiveTier(p),p.reason,bestTimes[p.id],S.cases[p.id].status,S.cases[p.id].owner]));break;}
 case 'export-tasks':exportTasks();break;
 case 'export-data':exportBlob('CareFlow_Synthetic_Data.json',JSON.stringify(DATA,null,2));break;
 case 'export-backup':exportBlob('CareFlow_Workspace_Backup.json',JSON.stringify({format:'carethread-backup-v1',synthetic:true,savedAt:new Date().toISOString(),state:S},null,2));break;
 case 'export-patient':exportPatient(id);break;
 case 'export-audit':csv('CareFlow_Activity.csv',['Time','Actor','Member','Action','Detail'],S.audit.map(a=>[a.at,a.actor,a.member,a.action,a.detail]));break;
 case 'export-metrics':exportBlob('CareFlow_Metrics.json',JSON.stringify({synthetic:true,contacts:S.contacts.length,reached:S.contacts.filter(c=>c.outcome.startsWith('Reached')).length,actionsCompleted:S.tasks.filter(t=>t.status==='Completed').length,signedNotes:S.notes.length,limitations:'Demo activity only. No clinical effectiveness claim.'},null,2));break;
 case 'download-html':downloadHTML();break;
 case 'download-zip':downloadZIP();break;
 case 'download-annex':downloadFile('annex','CareFlow_Synthetic_Patients.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break;
 case 'download-pdf':downloadFile('pdf','CareFlow_Presentation.pdf','application/pdf');break;
 case 'download-spec':downloadFile('spec','Workbench_Specification.md','text/markdown');break;
 case 'design-notes':showModal('Design references','Original implementation informed by public interaction patterns.',`<div class="stack">${DATA.refs.map(([name,url,fit,,borrow])=>`<div><h3><a href="${url}" target="_blank" rel="noopener noreferrer">${name} ${I('link')}</a></h3><p class="small muted">${fit}: ${borrow}</p></div>`).join('')}</div><p class="small muted" style="margin-top:20px">No proprietary application source was copied. Public documentation informed the navigation, queue, context panels and timeline.</p>`,btn('close-modal','Done'));break;
 case 'print-patient':closeModal();S.patientSection[id]='plan';S.dockOpen=false;render();setTimeout(()=>window.print(),100);break;
 case 'import-backup':$('#backup-file').click();break;
 case 'confirm-import':break;
 case 'reset-confirm':showModal('Reset this demo?','Download a backup first if you want to keep your work.',`<p class="small">This resets only CareFlow’s browser-local synthetic workspace. It clears demo edits, notes, contacts and tasks and restores the five original scenarios.</p>`,`${btn('close-modal','Keep my work')}${btn('reset-data','Reset demo','refresh','danger')}`);break;
 case 'reset-data':{let th=S.theme;S=initial();S.theme=th;persist();closeModal();render();toast('Original synthetic workspace restored.');break;}
 case 'shortcuts':showModal('Keyboard shortcuts','Navigation without leaving the keyboard.',`<div class="keyboard-list"><span>Search members and cases</span><kbd>Ctrl / ⌘ K</kbd><span>Go to work queue</span><kbd>Alt Q</kbd><span>Open user journeys</span><kbd>Alt J</kbd><span>Open notes for current member</span><kbd>Alt N</kbd><span>Close current dialog / exit journey</span><kbd>Esc</kbd><span>Resize focused separator</span><kbd>Arrow keys</kbd></div>`,btn('close-modal','Done'));break;
 case 'journeys':closeModal();goto('journeys');break;
 case 'start-journey':startJourney(id);ok=false;break;
 case 'exit-journey':endJourney(false);ok=false;break;
 case 'tour-do':{let t=tour&&$(`[data-tour="${tour.steps[tour.index].target}"]`);if(t)t.click();else returnToStep();return;}
 case 'tour-return':returnToStep();ok=false;break;
 default:toast('This control is unavailable in the current view.');ok=false;
}if(ok)advanceTour(event);});

document.addEventListener('input',e=>{const el=e.target;if(el.dataset.filter==='search'){S.filters.search=el.value;persist();$('#queue-results')&&($('#queue-results').innerHTML=queueTable());$('#case-results')&&($('#case-results').innerHTML=caseCards());}if(el.id==='global-search')$('#search-results').innerHTML=searchResults(el.value);if(el.dataset.draft){const id=el.dataset.draft,old=draftFor(id);S.drafts[id]={...old,text:el.value,reviewed:false,saved:false};const check=$('[data-field="review-note"]');if(check)check.checked=false;const st=$('#draft-status');if(st)st.textContent='Saving locally…';clearTimeout(window.draftTimer);window.draftTimer=setTimeout(()=>{if(S.drafts[id])S.drafts[id].saved=true;persist();if(S.active===id&&$('#draft-status'))$('#draft-status').textContent=storageAvailable?'Saved locally':'Storage unavailable';},450);}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter&&el.dataset.filter!=='search'){S.filters[el.dataset.filter]=el.value;persist();render();}switch(el.dataset.field){case 'review-note':{let dr=draftFor(el.dataset.id);S.drafts[el.dataset.id]={...dr,reviewed:el.checked};persist();if(el.checked)advanceTour('review-note');break;}case 'timeline-filter':S.timelineFilter=el.value;persist();render();break;case 'theme':S.theme=el.value;persist();render();break;case 'compact':S.compact=el.checked;persist();render();break;case 'sidebar':S.sidebarCollapsed=el.checked;persist();render();break;case 'context':S.context=el.checked;persist();render();break;case 'dock':S.dockOpen=el.checked;persist();render();break;}
if(el.name==='permission'&&el.checked)advanceTour('permission');});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch();return;}if(e.key==='Escape'){if(drawer){drawer=null;renderDrawer();}else if(modal)closeModal();else if(tour)endJourney(false);return;}if(e.altKey){if(e.key.toLowerCase()==='q'){e.preventDefault();goto('queue');}if(e.key.toLowerCase()==='j'){e.preventDefault();goto('journeys');}if(e.key.toLowerCase()==='n'&&S.active!=='home'){e.preventDefault();S.dockOpen=!S.dockOpen;persist();render();}}if(e.target.dataset.resize){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.target.dataset.resize==='context')S.contextWidth=Math.max(230,Math.min(460,S.contextWidth+(e.key==='ArrowLeft'?20:-20)));else S.dockHeight=Math.max(200,Math.min(480,S.dockHeight+(e.key==='ArrowUp'?20:-20)));document.documentElement.style.setProperty('--context',S.contextWidth+'px');document.documentElement.style.setProperty('--dock',S.dockHeight+'px');persist();}}if(e.key==='Tab'&&(modal||drawer)){const host=drawer?$('#drawer-root'):$('#modal-root'),els=$$('button:not(:disabled),input,textarea,select,a[href],[tabindex="0"]',host).filter(x=>x.getClientRects().length),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-resize]');if(!handle)return;const startX=e.clientX,startY=e.clientY,startW=S.contextWidth,startH=S.dockHeight;handle.setPointerCapture(e.pointerId);const move=ev=>{if(handle.dataset.resize==='context')S.contextWidth=Math.max(230,Math.min(460,startW+startX-ev.clientX));else S.dockHeight=Math.max(200,Math.min(480,startH+startY-ev.clientY));document.documentElement.style.setProperty('--context',S.contextWidth+'px');document.documentElement.style.setProperty('--dock',S.dockHeight+'px');};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);persist();};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);});
document.addEventListener('dragstart',e=>{const tab=e.target.closest('[data-tab]');if(tab){dragTab=tab.dataset.tab;tab.classList.add('dragging');e.dataTransfer.setData('text/plain',dragTab);}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-tab]'))e.preventDefault();});
document.addEventListener('drop',e=>{const tab=e.target.closest('[data-tab]');if(!tab||!dragTab)return;e.preventDefault();let a=S.tabs.indexOf(dragTab),b=S.tabs.indexOf(tab.dataset.tab);S.tabs.splice(a,1);S.tabs.splice(b,0,dragTab);dragTab=null;persist();render();});
document.addEventListener('dragend',()=>{$$('.dragging').forEach(e=>e.classList.remove('dragging'));dragTab=null;});
document.addEventListener('scroll',()=>{if(tour)requestAnimationFrame(()=>positionTour());},true);window.addEventListener('resize',()=>positionTour());
window.addEventListener('beforeunload',e=>{if(Object.values(S.drafts).some(d=>d.text&&!d.saved)){e.preventDefault();e.returnValue='';}});
window.addEventListener('offline',()=>{let n=document.createElement('div');n.id='offline';n.className='offlineline';n.textContent='Offline · synthetic workspace and downloads still work. Changes stay in this browser.';document.body.append(n);});window.addEventListener('online',()=>$('#offline')?.remove());
$('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const b=JSON.parse(await file.text());if(b.format!=='carethread-backup-v1'||b.synthetic!==true||!b.state||!Array.isArray(b.state.tasks)||!DATA.patients.every(p=>b.state.cases?.[p.id]))throw Error('Unsupported backup');if(b.state.tasks.some(t=>!patient(t.member)))throw Error('Unknown member');showModal('Restore this backup?','Your current workspace will be replaced. Download a current backup first if needed.',`<p class="small">Backup saved ${esc(b.savedAt)}. Contains ${b.state.tasks.length} tasks and ${b.state.notes?.length||0} signed notes.</p>`,`${btn('close-modal','Cancel')}${btn('confirm-import','Restore backup','refresh','primary')}`);window.pendingBackup=b.state;}catch{toast('Could not read this file. Choose a CareFlow synthetic workspace backup.');}e.target.value='';});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-import"]')&&window.pendingBackup){S=window.pendingBackup;window.pendingBackup=null;persist();closeModal();render();toast('Workspace backup restored.');}});
render();
